/** Find a preset by id */
export function getPresetById(id: string): FlowPreset | undefined {
	return FLOW_PRESETS.find((p) => p.id === id);
}

/**
 * Applies or removes the numerical prefix from a folder map.
 */
export function applyPrefixFormat(
	folderMap: FlowFolderMap,
	usePrefix: boolean
): FlowFolderMap {
	const result = { ...folderMap };
	for (const role of FLOW_ROLE_ORDER) {
		const roleIndex = FLOW_ROLE_ORDER.indexOf(role) + 1;
		const name = folderMap[role];
		const baseName = name.replace(/^\d+\.\s*/, "");
		result[role] = usePrefix ? `${roleIndex}. ${baseName}` : baseName;
	}
	return result;
}

/**
 * Detect the current preset based on existing vault folders.
 * Scans root folders and matches against known presets.
 * Supports folders with OR without number prefixes.
 */
export function detectCurrentPreset(rootFolderNames: string[]): { presetId: string; folderMap: Record<FlowRole, string>; usePrefix: boolean } | undefined {
	// Normalize: strip leading "N. " prefix for matching
	const stripPrefix = (name: string): string => name.replace(/^\d+\.\s*/, "");

	for (const preset of FLOW_PRESETS) {
		const presetNames = Object.values(preset.folders);
		const presetBareNames = presetNames.map(stripPrefix);

		// Check if all 6 preset folder names exist in the vault (with or without numbers)
		let matched = true;
		const detectedMap: Partial<Record<FlowRole, string>> = {};
		let usePrefixFound = false;

		for (const role of Object.keys(preset.folders) as FlowRole[]) {
			const presetName = preset.folders[role];
			const bareName = stripPrefix(presetName);

			// Try exact match first, then try bare name match
			const found = rootFolderNames.find((f) => f === presetName || stripPrefix(f) === bareName);
			if (found) {
				if (/^\d+\.\s*/.test(found)) {
					usePrefixFound = true;
				}
				detectedMap[role] = found; // Use the actual folder name on disk
			} else {
				matched = false;
				break;
			}
		}

		if (matched) {
			return { presetId: preset.id, folderMap: detectedMap as Record<FlowRole, string>, usePrefix: usePrefixFound };
		}
	}

	return undefined;
}

/**
 * Blueprint auto-detection utility.
 * Shared logic for discovering Blueprint files as missions.
 * Used by both Settings tab and Dashboard modal.
 */

import { TFile, TFolder, Vault } from "obsidian";
import { FlowFolderMap, FlowRole, VaultMission } from "../types";
import { findExistingFlowFolder } from "./folder-manager";
import { FLOW_PRESETS } from "../constants";

/**
 * Detect files in the Blueprint folder and return them as VaultMission objects.
 * Deduplicates against existing missions and tries multiple path lookups.
 *
 * @param vault The Obsidian vault
 * @param folderMap Current folder name mapping
 * @param existingMissions Already known missions (avoids duplicates)
 * @returns Combined list of existing + newly detected missions
 */
export function detectBlueprintMissions(
	vault: Vault,
	folderMap: FlowFolderMap,
	existingMissions: VaultMission[],
	language: "en" | "vi" = "en"
): VaultMission[] {
	const missions = [...existingMissions];
	const existingNames = new Set(missions.map((m) => m.name.toLowerCase()));

	// Try primary folder map first
	const blueprintFolderName = folderMap[FlowRole.BLUEPRINT];
	let blueprintFolder = findExistingFlowFolder(vault, blueprintFolderName);

	// Fallback: try all preset names for blueprint role
	if (!blueprintFolder) {
		for (const preset of FLOW_PRESETS) {
			blueprintFolder = findExistingFlowFolder(vault, preset.folders[FlowRole.BLUEPRINT]);
			if (blueprintFolder) break;
		}
	}

	if (!blueprintFolder) return missions;

	// Scan Blueprint folder for markdown files
	for (const child of blueprintFolder.children) {
		if (
			child instanceof TFile &&
			child.extension === "md" &&
			child.basename !== "0. TOC"
		) {
			if (!existingNames.has(child.basename.toLowerCase())) {
				missions.push({
					id: crypto.randomUUID
						? crypto.randomUUID()
						: Date.now().toString(36) + Math.random().toString(36).slice(2),
					name: child.basename,
					description: language === "vi" ? `Tự nhận diện trong vault` : `Auto-detected from vault`,
					relatedTags: [],
					status: "active",
				});
				existingNames.add(child.basename.toLowerCase());
			}
		}
	}

	return missions;
}

/**
 * Dashboard Modal
 * Displays a full-screen or large modal with Vault statistics.
 * Acts as a controller, delegating rendering to separate View components.
 */

import { App, Modal, setIcon } from "obsidian";
import type * as echarts from "echarts/core";
import { FlowPluginSettings, FlowRole } from "../../types";
import { VaultStats, collectVaultStats, invalidateStatsCache } from "./stats-collector";
import { renderFlowProgressionTab } from "./tabs/flow-progression";

// View Modules
import { NavigatorView } from "./views/navigator-view";
import { StatisticsView } from "./views/statistics-view";
import { TaxonomyView } from "./views/taxonomy-view";
import { TaskView } from "./views/task-view";

let echartsModule: typeof import("echarts/core") | null = null;
async function getECharts() {
	if (!echartsModule) {
		const mod = await import("../../utils/echarts-setup");
		echartsModule = mod.default;
	}
	return echartsModule;
}

type DashboardTab = "properties" | "tags" | "activity" | "mood" | "taxonomy";
export type DashboardView = "statistics" | "navigator" | "flow" | "tasks";

export class DashboardModal extends Modal {
	private settings: FlowPluginSettings;
	private activeView: DashboardView = "flow";
	private activeTab: DashboardTab = "activity";
	private stats: VaultStats | null = null;

	private controlsContainer: HTMLElement | null = null;
	private chartContainer: HTMLElement | null = null;
	private navigatorContainer: HTMLElement | null = null;
	private taskContainer: HTMLElement | null = null;
	private overviewContainer: HTMLElement | null = null;
	private viewToggleBar: HTMLElement | null = null;

	// View Controllers
	private navigatorViewInstance: NavigatorView | null = null;
	private statisticsViewInstance: StatisticsView | null = null;
	private taxonomyViewInstance: TaxonomyView | null = null;
	private taskViewInstance: TaskView | null = null;

	constructor(app: App, settings: FlowPluginSettings, initialView: DashboardView = "flow") {
		super(app);
		this.settings = settings;
		this.activeView = initialView;
	}

	async onOpen() {
		const { contentEl } = this;
		contentEl.addClass("flow-dashboard-modal");

		// Set modal geometry
		this.modalEl.addClass("flow-dashboard-ui-1");

		contentEl.empty();

		// Header Row
		const headerContainer = contentEl.createDiv("flow-dashboard-header");
		headerContainer.setCssProps({ "display": "flex" })
		headerContainer.setCssProps({ "justify-content": "center" })
		headerContainer.setCssProps({ "align-items": "center" })
		headerContainer.setCssProps({ "position": "relative" })
		const titleRow = headerContainer.createDiv();
		titleRow.setCssProps({ "display": "flex", "align-items": "center", "justify-content": "center", "gap": "8px" })
		const wavesIcon = titleRow.createSpan();
		setIcon(wavesIcon, "waves");
		wavesIcon.setCssProps({ "display": "flex", "align-items": "center", "color": "var(--text-accent)" })
		titleRow.createEl("h2", { text: "FLOW Dashboard", cls: "flow-dashboard-title" });
		titleRow.querySelector("h2")!.style.margin = "0";


		this.overviewContainer = contentEl.createDiv("flow-overview-container");
		this.overviewContainer.setCssProps({ "margin-top": "24px" })

		// Top-level view toggle: Statistics vs Navigator
		this.renderViewToggle(contentEl);

		// Chart sub-tabs (only visible in Statistics mode)
		this.renderTabs(contentEl);

		// Controls container
		this.controlsContainer = contentEl.createDiv("flow-dashboard-controls");
		this.controlsContainer.setCssProps({ "margin-bottom": "10px" })
		this.controlsContainer.setCssProps({ "display": "flex" })
		this.controlsContainer.setCssProps({ "justify-content": "center" })
		this.renderControls();

		// Chart container
		this.chartContainer = contentEl.createDiv("flow-chart-container");
		this.chartContainer.addClass("flow-dashboard-ui-2");
		this.chartContainer.setCssProps({ "display": "flex" })
		this.chartContainer.addClass("flow-dashboard-ui-3");

		// Navigator container
		this.navigatorContainer = contentEl.createDiv("flow-navigator-container");
		this.navigatorContainer.addClass("flow-dashboard-ui-4");
		this.navigatorContainer.setCssProps({ "display": "none" })

		// Task container
		this.taskContainer = contentEl.createDiv("flow-task-container");
		this.taskContainer.addClass("flow-dashboard-ui-task"); // Use a semantic class or similar structure
		this.taskContainer.setCssProps({ "display": "none" })
		this.taskContainer.setCssProps({ "height": "100%" }) // Needed for scrolling list

		// Preload ECharts module if needed
		const echartsLoaded = await getECharts();

		// Initialize View Controllers
		this.navigatorViewInstance = new NavigatorView(this.app, this.settings, this.navigatorContainer, () => this.close());
		this.statisticsViewInstance = new StatisticsView(this.app, this.settings, this.chartContainer, echartsLoaded);
		this.taxonomyViewInstance = new TaxonomyView(this.app, this.settings, this.chartContainer, echartsLoaded);
		this.taskViewInstance = new TaskView(this.app, this.settings, this.taskContainer, () => this.close());

		window.addEventListener("resize", this.handleResize);

		// Data collection
		invalidateStatsCache();
		this.stats = collectVaultStats(this.app, this.settings.folderMap, this.settings);

		// Persist cache
		this.settings.lastCachedStats = this.stats as unknown as Record<string, unknown>;
		const plugin = (this.app as unknown).plugins?.plugins?.["obsidian-flow"];
		if (plugin && plugin.saveSettings) plugin.saveSettings();

		// Render immediately
		if (this.overviewContainer) {
			this.renderOverviewRow(this.overviewContainer);
		}
		this.renderView();
	}

	onClose() {
		const { contentEl } = this;
		contentEl.empty();
		window.removeEventListener("resize", this.handleResize);

		if (this.statisticsViewInstance) this.statisticsViewInstance.destroy();
		if (this.taxonomyViewInstance) this.taxonomyViewInstance.destroy();
	}

	private handleResize = () => {
		if (this.activeView === "statistics") {
			if (this.activeTab === "taxonomy") {
				if (this.taxonomyViewInstance) this.taxonomyViewInstance.resize();
			} else {
				if (this.statisticsViewInstance) this.statisticsViewInstance.resize();
			}
		}
	};

	private renderOverviewRow(container: HTMLElement) {
		if (!this.stats) return;

		const row = container.createDiv("flow-dashboard-overview");

		const createStatBox = (iconName: string, label: string, value: string | number) => {
			const box = row.createDiv("flow-stat-box");
			const titleWrap = box.createDiv("flow-stat-label");
			titleWrap.setCssProps({ "display": "flex" })
			titleWrap.setCssProps({ "align-items": "center" })
			titleWrap.setCssProps({ "gap": "6px" })
			titleWrap.setCssProps({ "justify-content": "center" })

			const iconEl = titleWrap.createSpan();
			setIcon(iconEl, iconName);
			(iconEl.querySelector("svg") as SVGElement)?.setAttribute("width", "14");
			(iconEl.querySelector("svg") as SVGElement)?.setAttribute("height", "14");

			titleWrap.createSpan({ text: label });
			box.createDiv("flow-stat-value").setText(String(value));
		};

		createStatBox("file-text", this.settings.language === "vi" ? "TỔNG GHI CHÚ HOẠT ĐỘNG" : "TOTAL ACTIVE NOTES", this.stats.totalActiveNotes);

		createStatBox("inbox", "CAPTURE", this.stats.notesPerFolder[FlowRole.CAPTURE] || 0);
		createStatBox("calendar", "TRACK", this.stats.notesPerFolder[FlowRole.TRACK] || 0);
		createStatBox("hammer", "FORGE", this.stats.notesPerFolder[FlowRole.FORGE] || 0);
		createStatBox("library", "EXHIBIT", this.stats.notesPerFolder[FlowRole.EXHIBIT] || 0);
	}

	private renderViewToggle(container: HTMLElement) {
		if (!this.viewToggleBar) {
			this.viewToggleBar = container.createDiv("flow-view-toggle");
			this.viewToggleBar.setCssProps({ "display": "flex" })
			this.viewToggleBar.addClass("flow-dashboard-ui-5");
		}
		this.viewToggleBar.empty();

		const isVi = this.settings.language === "vi";
		const views: { id: DashboardView; label: string; icon: string }[] = [
			{ id: "flow", label: isVi ? "Tiến trình" : "Progress", icon: "activity" },
			{ id: "navigator", label: isVi ? "Bảng nội dung" : "Navigator", icon: "table" },
			{ id: "tasks", label: isVi ? "Nhiệm vụ" : "Tasks", icon: "check-square" },
			{ id: "statistics", label: isVi ? "Thống kê" : "Statistics", icon: "bar-chart-2" },
		];

		for (const v of views) {
			const isActive = this.activeView === v.id;
			const btn = this.viewToggleBar.createEl("button");
			btn.addClass("flow-view-btn");
			if (isActive) btn.addClass("active");

			const iconEl = btn.createSpan();
			setIcon(iconEl, v.icon);
			btn.createSpan({ text: v.label });

			btn.addEventListener("click", () => {
				if (this.activeView === v.id) return;
				this.activeView = v.id;
				this.renderViewToggle(container);
				this.renderView();
			});
		}
	}

	private renderTabs(container: HTMLElement) {
		const tabBar = container.createDiv("flow-tabs");
		tabBar.id = "flow-chart-tabs";

		const isVi = this.settings.language === "vi";
		let tabs: { id: DashboardTab; name: string; icon: string }[] = [
			{ id: "activity", name: isVi ? "Hoạt động" : "Activity", icon: "activity" },
			{ id: "mood", name: isVi ? "Tâm trạng" : "Mood Tracking", icon: "smile" },
			{ id: "properties", name: isVi ? "Thuộc tính" : "Properties", icon: "list-tree" },
			{ id: "tags", name: isVi ? "Thẻ" : "Tags", icon: "tags" },
			{ id: "taxonomy", name: isVi ? "Phân loại" : "Taxonomy", icon: "git-branch" },
		];

		// Default to always showing mood tab as requested
		// const hasMoodData = this.stats && (Object.keys(this.stats.moodByDate).length > 0 || Object.keys(this.stats.feelingCounts).length > 0);
		// if (!hasMoodData) {
		// 	tabs = tabs.filter(t => t.id !== "mood");
		// 	if (this.activeTab === "mood") this.activeTab = "activity";
		// }

		for (const tab of tabs) {
			const btn = tabBar.createDiv(`flow-tab ${this.activeTab === tab.id ? "active" : ""}`);
			setIcon(btn, tab.icon);
			btn.createSpan({ text: tab.name });

			btn.addEventListener("click", () => {
				if (this.activeTab === tab.id) return;
				tabBar.querySelectorAll(".flow-tab").forEach(t => t.removeClass("active"));
				btn.addClass("active");

				this.activeTab = tab.id;
				this.renderControls();
				this.renderView();
			});
		}
	}

	private renderControls() {
		if (!this.controlsContainer) return;
		this.controlsContainer.empty();
	}

	private renderView() {
		if (!this.chartContainer || !this.navigatorContainer || !this.taskContainer) return;
		const tabBar = this.contentEl.querySelector("#flow-chart-tabs") as HTMLElement;

		if (this.activeView === "navigator") {
			this.chartContainer.setCssProps({ "display": "none" })
			if (this.controlsContainer) this.controlsContainer.setCssProps({ "display": "none" })
			if (tabBar) tabBar.setCssProps({ "display": "none" })
			if (this.overviewContainer) this.overviewContainer.setCssProps({ "display": "" })
			this.taskContainer.setCssProps({ "display": "none" })
			this.navigatorContainer.setCssProps({ "display": "block" })

			if (this.stats && this.navigatorViewInstance) {
				this.navigatorViewInstance.render(this.stats);
			}
		} else if (this.activeView === "tasks") {
			this.chartContainer.setCssProps({ "display": "none" })
			this.navigatorContainer.setCssProps({ "display": "none" })
			if (this.controlsContainer) this.controlsContainer.setCssProps({ "display": "none" })
			if (tabBar) tabBar.setCssProps({ "display": "none" })
			if (this.overviewContainer) this.overviewContainer.setCssProps({ "display": "" })
			this.taskContainer.setCssProps({ "display": "block" })

			if (this.stats && this.taskViewInstance) {
				this.taskViewInstance.render(this.stats);
			}
		} else if (this.activeView === "flow") {
			this.navigatorContainer.setCssProps({ "display": "none" })
			this.taskContainer.setCssProps({ "display": "none" })
			if (tabBar) tabBar.setCssProps({ "display": "none" })
			if (this.controlsContainer) this.controlsContainer.setCssProps({ "display": "none" })
			if (this.overviewContainer) this.overviewContainer.setCssProps({ "display": "none" })

			// Clean up previous charts if any
			if (this.statisticsViewInstance) this.statisticsViewInstance.destroy();
			if (this.taxonomyViewInstance) this.taxonomyViewInstance.destroy();

			this.chartContainer.setCssProps({ "display": "flex" })
			this.chartContainer.empty();

			if (this.stats) {
				renderFlowProgressionTab(this.chartContainer, this.stats, this.app, this.settings);
			}
		} else { // Statistics mode
			this.navigatorContainer.setCssProps({ "display": "none" })
			this.taskContainer.setCssProps({ "display": "none" })
			if (tabBar) tabBar.setCssProps({ "display": "flex" })
			if (this.controlsContainer) this.controlsContainer.setCssProps({ "display": "flex" })
			if (this.overviewContainer) this.overviewContainer.setCssProps({ "display": "" })
			this.chartContainer.setCssProps({ "display": "flex" })

			this.renderControls();

			if (this.stats) {
				if (this.activeTab === "taxonomy") {
					if (this.statisticsViewInstance) this.statisticsViewInstance.destroy();
					if (this.taxonomyViewInstance) this.taxonomyViewInstance.render(this.stats);
				} else {
					if (this.taxonomyViewInstance) this.taxonomyViewInstance.destroy();
					if (this.statisticsViewInstance) this.statisticsViewInstance.render(this.stats, this.activeTab);
				}
			}
		}
	}
}

/**
 * FLOW Health Scorer — Computes a 0–100 health score per stage.
 *
 * Each stage has weighted criteria. Scores are clamped to [0, 100].
 * Three levels: 🔴 Basic (0–40), 🟡 Good (41–70), 🟢 Advanced (71–100).
 */

import { FlowPluginSettings, FlowRole, VaultMission } from "../../types";
import { VaultStats, RoleStats } from "./stats-collector";

// ── Types ───────────────────────────────────────────────────────────────

export interface CriterionResult {
	name: string;
	nameVi: string;
	score: number;
	maxScore: number;
	level: "basic" | "good" | "advanced";
}

export interface StageHealthResult {
	totalScore: number;
	level: "basic" | "good" | "advanced";
	criteria: CriterionResult[];
	evaluationText?: string;
}

// ── Helpers ─────────────────────────────────────────────────────────────

function clamp(v: number, min: number, max: number): number {
	return Math.max(min, Math.min(max, v));
}

function toLevel(score: number, max: number): "basic" | "good" | "advanced" {
	const pct = max > 0 ? (score / max) * 100 : 0;
	if (pct >= 71) return "advanced";
	if (pct >= 41) return "good";
	return "basic";
}

function criterion(name: string, nameVi: string, score: number, maxScore: number): CriterionResult {
	return { name, nameVi, score: clamp(Math.round(score), 0, maxScore), maxScore, level: toLevel(score, maxScore) };
}

// ── Universal: Folder Organization ──────────────────────────────────────

function folderOrgScore(rs: RoleStats, maxPts: number, settings: FlowPluginSettings): CriterionResult {
	let score = maxPts;
	const totalNotes = rs.noteCount;
	const hs = settings.healthScoring;
	const allowedDepth = hs.maxSubfolderDepth;
	const maxNotes = hs.maxNotesPerFolder;
	const maxRoot = hs.maxRootNotes;
	if (totalNotes === 0) return criterion("Folder Organization", "Tổ chức thư mục", 0, maxPts);

	// Rule 1: Deep nesting penalty
	if (rs.maxFolderDepth > allowedDepth) {
		const excess = rs.maxFolderDepth - allowedDepth;
		score -= excess * 5;
	}

	// Rule 2: Flat structure with too many notes (no subfolders but > maxNotes)
	if (rs.subfolderCount === 0 && totalNotes > maxNotes) {
		score -= 8;
	}

	// Rule 3: Per-subfolder balance (max ± 2 ideal)
	const subfolders = Object.entries(rs.notesPerSubfolder);
	for (const [, count] of subfolders) {
		if (count > maxNotes) score -= 2;       // overfull subfolder
		if (count === 0) score -= 2;             // empty subfolder
		if (count > 0 && count < 2) score -= 1;  // too few (premature split)
	}

	// Rule 4: Root notes balance
	if (rs.notesInRoot > maxRoot) score -= 3;

	return criterion("Folder Organization", "Tổ chức thư mục", score, maxPts);
}

// ── BLUEPRINT ───────────────────────────────────────────────────────────

function scoreBlueprint(rs: RoleStats, stats: VaultStats, settings: FlowPluginSettings): StageHealthResult {
	const missions = settings.vaultMissions || [];
	const activeMissions = missions.filter(m => m.status === "active");

	// 1. Mission defined (25)
	const c1 = criterion("Missions Defined", "Nhiệm vụ được định nghĩa",
		missions.length >= 1 ? 25 : 0, 25);

	// 2. Properties on notes (20)
	const propRate = rs.noteCount > 0 ? rs.notesWithProperties / rs.noteCount : 0;
	const c2 = criterion("Properties Usage", "Sử dụng Properties",
		propRate * 20, 20);

	// 3. Wikilink/MOC creation (20)
	const linkRate = rs.noteCount > 0 ? rs.notesWithWikilinks / rs.noteCount : 0;
	const c3 = criterion("Wikilink / MOC", "Liên kết / MOC",
		linkRate * 20, 20);

	// 4. Tags (10)
	const missionsWithTags = missions.filter(m => m.relatedTags && m.relatedTags.length > 0).length;
	const c4 = criterion("Mission Tags", "Tag cho nhiệm vụ",
		Math.min(missionsWithTags * 5, 10), 10);

	// 5. Folder organization (25)
	const c5 = folderOrgScore(rs, 25, settings);

	const criteria = [c1, c2, c3, c4, c5];
	const totalScore = clamp(criteria.reduce((a, c) => a + c.score, 0), 0, 100);
	const level = toLevel(totalScore, 100);

	const isVi = settings.language !== "en";
	let evaluationText = "";
	if (totalScore >= 71) {
		evaluationText = isVi ? "Bản thiết kế tuyệt vời. Sứ mệnh được xác định rõ ràng và liên kết tốt với các ghi chú khác." : "Excellent blueprint. Missions are well-defined and highly interlinked.";
	} else if (totalScore >= 41) {
		evaluationText = isVi ? "Cơ bản ổn, nhưng cần tăng cường sử dụng Properties và gắn tag cho các sứ mệnh để dễ tìm kiếm." : "Fair structure. Improve by utilizing Properties more and adding tags to missions.";
	} else {
		evaluationText = isVi ? "Thiếu định hướng cốt lõi. Hãy tạo thêm các sứ mệnh (Mission) và đảm bảo các ghi chú được liên kết chặt chẽ." : "Lacks core direction. Create more missions and ensure notes are interlinked.";
	}

	return { totalScore, level, criteria, evaluationText };
}

// ── CAPTURE ─────────────────────────────────────────────────────────────

function scoreCapture(rs: RoleStats, stats: VaultStats, settings: FlowPluginSettings): StageHealthResult {
	const forgeRs = stats.roleStats[FlowRole.FORGE];
	const total = rs.noteCount;

	// 1. Flow balance (15)
	let flowPts = 0;
	if (total === 0 && (!forgeRs || forgeRs.noteCount === 0)) flowPts = 0;
	else if (total > 0 && forgeRs && forgeRs.noteCount > 0) flowPts = 15;
	else if (total > 0 && (!forgeRs || forgeRs.noteCount === 0)) flowPts = 5;
	else flowPts = 10;
	const c1 = criterion("Flow Balance", "Cân bằng luồng", flowPts, 15);

	// 2. Staleness (20) — average age of capture notes
	let stalePts = 20;
	const [sGood, sWarn, sBad] = settings.healthScoring.staleThresholdDays;
	if (stats.captureNoteAges.length > 0) {
		const avgAge = stats.captureNoteAges.reduce((a, b) => a + b, 0) / stats.captureNoteAges.length;
		if (avgAge > sBad) stalePts = 0;
		else if (avgAge > sWarn) stalePts = 5;
		else if (avgAge > sGood) stalePts = 12;
		else stalePts = 20;
	}
	const c2 = criterion("Freshness", "Độ tươi mới", stalePts, 20);

	// 3. Metadata coverage (25) — tiered at good%/excellent%
	const [metaGood, metaExc] = settings.healthScoring.metaCoverageThresholds;
	const metaRate = total > 0 ? rs.notesWithAnyMetadata / total : 0;
	let metaPts = 0;
	if (metaRate >= metaExc / 100) metaPts = 25;
	else if (metaRate >= metaGood / 100) metaPts = 15;
	else if (metaRate > 0) metaPts = 5;
	const c3 = criterion("Metadata Coverage", "Bao phủ Metadata", metaPts, 25);

	// 4. Wikilink enrichment (15)
	const linkRate = total > 0 ? rs.captureHasWikilink / total : 0;
	const c4 = criterion("Wikilinks", "Liên kết", linkRate * 15, 15);

	// 5. Folder organization (25)
	const c5 = folderOrgScore(rs, 25, settings);

	const criteria = [c1, c2, c3, c4, c5];
	const totalScore = clamp(criteria.reduce((a, c) => a + c.score, 0), 0, 100);
	const level = toLevel(totalScore, 100);

	const isVi = settings.language !== "en";
	let evaluationText = "";
	if (totalScore >= 71) {
		evaluationText = isVi ? "Quá trình thu thập đang hoạt động rất hiệu quả. Ghi chú mới được xử lý nhanh và gắn kết tốt." : "Capture is highly effective. New notes are processed quickly and well-linked.";
	} else if (totalScore >= 41) {
		evaluationText = isVi ? "Khá tốt. Hãy chú ý xử lý các ghi chú thô (raw notes) tồn đọng lâu ngày và bổ sung liên kết (Wikilinks)." : "Good. Pay attention to older raw notes and add more Wikilinks.";
	} else {
		evaluationText = isVi ? "Nhiều ghi chú thu thập bị bỏ quên hoặc thiếu metadata. Hãy dọn dẹp ghi chú thô và phân loại kịp thời." : "Many captured notes are neglected or lack metadata. Process raw notes and classify them promptly.";
	}

	return { totalScore, level, criteria, evaluationText };
}

// ── TRACK ───────────────────────────────────────────────────────────────

function scoreTrack(rs: RoleStats, stats: VaultStats, settings: FlowPluginSettings): StageHealthResult {
	const done = rs.trackTasksCompleted;
	const pending = rs.trackTasksPending;
	const total = rs.noteCount;

	// 1. Task completion (25)
	const taskT = done + pending;
	let completionPts = 12; // neutral
	if (taskT > 0) completionPts = (done / taskT) * 25;
	const c1 = criterion("Task Completion", "Hoàn thành nhiệm vụ", completionPts, 25);

	// 2. Consistency (15)
	let consPts = 0;
	if (total >= 30) consPts = 15;
	else if (total >= 15) consPts = 12;
	else if (total >= 7) consPts = 8;
	else if (total >= 1) consPts = 4;
	const c2 = criterion("Consistency", "Tần suất", consPts, 15);

	// 3. Emotional tracking (15)
	const feelRate = total > 0 ? rs.trackHasFeeling / total : 0;
	const c3 = criterion("Emotion Tracking", "Theo dõi cảm xúc", feelRate * 15, 15);

	// 4. Progress bonus (10) — optional, notes with progress=done get bonus
	const progressDist = rs.forgeProgressDistribution || {};
	const doneCount = progressDist["done"] || 0;
	let progPts = 5; // neutral
	if (Object.keys(progressDist).length > 0 && doneCount > 0) progPts = 10;
	const c4 = criterion("Progress Tracking", "Theo dõi tiến trình", progPts, 10);

	// 5. Pending backlog (10)
	let backlogPts = 0;
	if (pending === 0) backlogPts = 10;
	else if (pending <= 3) backlogPts = 7;
	else if (pending <= 7) backlogPts = 3;
	const c5 = criterion("Backlog", "Tồn đọng", backlogPts, 10);

	// 6. Folder organization (25)
	const c6 = folderOrgScore(rs, 25, settings);

	const criteria = [c1, c2, c3, c4, c5, c6];
	const totalScore = clamp(criteria.reduce((a, c) => a + c.score, 0), 0, 100);
	const level = toLevel(totalScore, 100);

	const isVi = settings.language !== "en";
	let evaluationText = "";
	if (totalScore >= 71) {
		evaluationText = isVi ? "Theo dõi cực tốt! Bạn duy trì thói quen ghi chú đều đặn và giải quyết công việc tồn đọng rất hiệu quả." : "Excellent tracking! You maintain a consistent logging habit and resolve pending tasks efficiently.";
	} else if (totalScore >= 41) {
		evaluationText = isVi ? "Tốt, nhưng lượng task tồn đọng bắt đầu tích tụ. Hãy rà soát lại tiến trình và dọn dẹp task cũ." : "Good, but pending tasks are accumulating. Review your progress and clear old tasks.";
	} else {
		evaluationText = isVi ? "Tần suất theo dõi thấp và nhiều việc tồn đọng. Cần tạo thói quen ghi log hàng ngày và xử lý dứt điểm task." : "Low tracking frequency and high backlog. Build a daily logging habit and clear pending tasks.";
	}

	return { totalScore, level, criteria, evaluationText };
}

// ── FORGE ───────────────────────────────────────────────────────────────

function scoreForge(rs: RoleStats, stats: VaultStats, settings: FlowPluginSettings): StageHealthResult {
	const hm = rs.forgeHeatmap || {};
	const totalFolders = Object.keys(hm).length;
	const hotCount = Object.values(hm).filter(v => v === "hot").length;
	const warmCount = Object.values(hm).filter(v => v === "warm").length;
	const coldCount = Object.values(hm).filter(v => v === "cold").length;
	const activeCount = hotCount + warmCount;

	// 1. Active ratio (25)
	let activeRate = totalFolders > 0 ? activeCount / totalFolders : 0;
	let activePts = 5;
	if (activeRate > 0.6) activePts = 25;
	else if (activeRate > 0.4) activePts = 15;
	const c1 = criterion("Active Ratio", "Tỷ lệ hoạt động", activePts, 25);

	// 2. Progress distribution (20) — mediumRate
	const dist = rs.forgeProgressDistribution || {};
	const distTotal = Object.values(dist).reduce((a, b) => a + b, 0);
	const mediumCount = dist["medium"] || 0;
	const mediumRate = distTotal > 0 ? mediumCount / distTotal : 0;
	const c2 = criterion("Progress Distribution", "Phân bổ tiến trình", mediumRate * 20, 20);

	// 3. Metadata quality (15)
	const metaRate = rs.noteCount > 0 ? rs.notesWithAnyMetadata / rs.noteCount : 0;
	const c3 = criterion("Metadata Quality", "Chất lượng Metadata", metaRate * 15, 15);

	// 4. Cold stagnation (15) — ratio-based
	const coldRate = totalFolders > 0 ? coldCount / totalFolders : 0;
	let coldPts = 15;
	if (coldRate >= 0.4) coldPts = 5;
	else if (coldRate >= 0.2) coldPts = 10;
	const c4 = criterion("Cold Stagnation", "Dự án ngủ đông", coldPts, 15);

	// 5. Folder organization (25)
	const c5 = folderOrgScore(rs, 25, settings);

	const criteria = [c1, c2, c3, c4, c5];
	const totalScore = clamp(criteria.reduce((a, c) => a + c.score, 0), 0, 100);
	const level = toLevel(totalScore, 100);

	const isVi = settings.language !== "en";
	let evaluationText = "";
	if (totalScore >= 71) {
		evaluationText = isVi ? "Tiến trình Rèn giũa rất sôi nổi. Các dự án đang được phát triển liên tục và không bị đình trệ." : "Forge process is highly active. Projects are continuously developed without stagnation.";
	} else if (totalScore >= 41) {
		evaluationText = isVi ? "Có sự phát triển, nhưng một số dự án đang bị 'ngủ đông'. Hãy tập trung hoàn thiện các bản nháp đang dang dở." : "Progress exists, but some projects are dormant. Focus on completing WIP drafts.";
	} else {
		evaluationText = isVi ? "Rất nhiều nội dung đang đình trệ hoặc thiếu metadata. Cần kích hoạt lại các dự án hoặc đưa vào Lưu trữ." : "Many contents are stagnant or lack metadata. Reactivate projects or move them to Vault.";
	}

	return { totalScore, level, criteria, evaluationText };
}

// ── EXHIBIT ─────────────────────────────────────────────────────────────

function scoreExhibit(rs: RoleStats, stats: VaultStats, settings: FlowPluginSettings): StageHealthResult {
	const total = rs.noteCount;

	// 1. Tag diversity (20)
	const uniqueTags = Object.keys(rs.tagsCount).length;
	let tagPts = 0;
	if (uniqueTags >= 5) tagPts = 20;
	else if (uniqueTags >= 3) tagPts = 15;
	else if (uniqueTags >= 1) tagPts = 8;
	const c1 = criterion("Tag Diversity", "Đa dạng Tag", tagPts, 20);

	// 2. Properties usage (20)
	const propRate = total > 0 ? rs.notesWithProperties / total : 0;
	const c2 = criterion("Properties Usage", "Sử dụng Properties", propRate * 20, 20);

	// 3. Content volume (10)
	let volPts = 0;
	if (total >= 5) volPts = 10;
	else if (total >= 1) volPts = 6;
	const c3 = criterion("Content Volume", "Số lượng nội dung", volPts, 10);

	// 4. Subfolder/notes balance (25)
	const c4 = folderOrgScore(rs, 25, settings);

	// 5. Notes-per-subfolder (25)
	const maxNotes = settings.healthScoring.maxNotesPerFolder;
	let npsScore = 25;
	if (rs.subfolderCount === 0 && total > 0) npsScore = 5; // flat, no structure
	else if (rs.subfolderCount > 0) {
		// Check if subfolders are balanced
		const counts = Object.values(rs.notesPerSubfolder);
		const emptyFolders = counts.filter(c => c === 0).length;
		const overflowFolders = counts.filter(c => c > maxNotes).length;
		npsScore -= emptyFolders * 3;
		npsScore -= overflowFolders * 3;
	}
	const c5 = criterion("Structure Balance", "Cân bằng cấu trúc", npsScore, 25);

	const criteria = [c1, c2, c3, c4, c5];
	const totalScore = clamp(criteria.reduce((a, c) => a + c.score, 0), 0, 100);
	const level = toLevel(totalScore, 100);

	const isVi = settings.language !== "en";
	let evaluationText = "";
	if (totalScore >= 71) {
		evaluationText = isVi ? "Nội dung trưng bày chất lượng cao! Đa dạng tag và hệ thống Properties được chuẩn hoá tốt." : "High-quality exhibit content! Diverse tags and well-standardized Properties system.";
	} else if (totalScore >= 41) {
		evaluationText = isVi ? "Nội dung ổn nhưng cấu trúc thư mục chưa cân bằng. Hãy chú ý gom nhóm và phân bổ nội dung hợp lý hơn." : "Content is fine but folder structure is unbalanced. Group and distribute content better.";
	} else {
		evaluationText = isVi ? "Kho trưng bày đang thiếu hụt sự tổ chức. Hãy bắt đầu gán tag, Properties rõ ràng và chia thư mục." : "Exhibit lacks organization. Start assigning clear tags, Properties, and organize folders.";
	}

	return { totalScore, level, criteria, evaluationText };
}

// ── VAULT ───────────────────────────────────────────────────────────────

function scoreVault(rs: RoleStats | undefined, stats: VaultStats, settings: FlowPluginSettings): StageHealthResult {
	// Vault doesn't have a RoleStats entry (tracked globally), so use global stats.

	// 1. Naming Consistency (20)
	const naming = stats.namingConventions;
	const totalNamed = naming.zettelkasten + naming.natural + naming.kebab + naming.snake + naming.camel + naming.pascal + naming.other;
	const maxStyleCount = Math.max(naming.zettelkasten, naming.natural, naming.kebab, naming.snake, naming.camel, naming.pascal);
	const consistencyRate = totalNamed > 0 ? maxStyleCount / totalNamed : 0;

	let namingPts = 0;
	if (consistencyRate > 0.8) namingPts = 15;
	else if (consistencyRate > 0.5) namingPts = 10;
	else namingPts = 5;

	// Bonus for Zettelkasten / JD
	if (totalNamed > 0 && naming.zettelkasten > totalNamed * 0.1) namingPts += 5;

	const c1 = criterion("Naming Consistency", "Độ nhất quán tên tệp", namingPts, 20);

	// 2. Orphan cleanup (20)
	const [orphGood, orphWarn, orphBad] = settings.healthScoring.orphanRateThresholds;
	const orphanRate = stats.vaultTotalSize > 0
		? stats.orphanedAttachmentsSize / stats.vaultTotalSize
		: 0;
	let orphanPts = 0;
	if (orphanRate < orphGood / 100) orphanPts = 20;
	else if (orphanRate < orphWarn / 100) orphanPts = 12;
	else if (orphanRate < orphBad / 100) orphanPts = 6;
	const c2 = criterion("Orphan Cleanup", "Dọn dẹp tệp mồ côi", orphanPts, 20);

	// 3. File size hygiene (20)
	const [overWarn, overBad] = settings.healthScoring.oversizedFileThresholds;
	const oversized = stats.oversizedFiles.length;
	let filePts = 20;
	if (oversized > overBad) filePts = 5;
	else if (oversized > overWarn) filePts = 10;
	else if (oversized > 0) filePts = 15;
	const c3 = criterion("File Size Hygiene", "Dung lượng tệp", filePts, 20);

	// 4. Version Control (15)
	const c4 = criterion("Version Control", "Quản lý phiên bản",
		stats.hasGitRepo ? 15 : 0, 15);

	// 5. Folder organization (25)
	const c5 = rs
		? folderOrgScore(rs, 25, settings)
		: criterion("Folder Organization", "Tổ chức thư mục", 15, 25);

	const criteria = [c1, c2, c3, c4, c5];
	const totalScore = clamp(criteria.reduce((a, c) => a + c.score, 0), 0, 100);
	const level = toLevel(totalScore, 100);

	const isVi = settings.language !== "en";
	let evaluationText = "";
	if (totalScore >= 71) {
		evaluationText = isVi ? "Kho lưu trữ gọn gàng, quy tắc đặt tên thống nhất và tệp mồ côi được kiểm soát cực tốt." : "Vault is tidy, naming conventions are consistent, and orphaned files are well controlled.";
	} else if (totalScore >= 41) {
		evaluationText = isVi ? "Lưu trữ tương đối ổn định. Nên dọn bớt các tệp đính kèm mồ côi (không sử dụng) để tiết kiệm dung lượng." : "Storage is relatively stable. Consider cleaning up orphaned attachments to save space.";
	} else {
		evaluationText = isVi ? "Kho lưu trữ lộn xộn. Đang có quá nhiều tệp lớn, tệp mồ côi và thiếu sự nhất quán trong cách đặt tên." : "Vault is cluttered. Too many large files, orphaned files, and inconsistent naming.";
	}

	return { totalScore, level, criteria, evaluationText };
}

// ── Public API ──────────────────────────────────────────────────────────

export function computeAllHealthScores(
	stats: VaultStats,
	settings: FlowPluginSettings
): Record<string, StageHealthResult> {
	const bpRs = stats.roleStats[FlowRole.BLUEPRINT];
	const capRs = stats.roleStats[FlowRole.CAPTURE];
	const trkRs = stats.roleStats[FlowRole.TRACK];
	const frgRs = stats.roleStats[FlowRole.FORGE];
	const exhRs = stats.roleStats[FlowRole.EXHIBIT];

	const emptyRs: RoleStats = {
		noteCount: 0, propertiesGrouped: {}, tagsCount: {},
		notesWithAnyMetadata: 0, notesWithTags: 0, notesWithProperties: 0,
		notesWithWikilinks: 0, maxFolderDepth: 0, subfolderCount: 0,
		notesInRoot: 0, notesPerSubfolder: {},
		captureHasWikilink: 0, captureRawNotes: 0,
		trackTasksCompleted: 0, trackTasksPending: 0, trackHasFeeling: 0,
		forgeWipCount: 0, forgeHeatmap: {}, forgeProgressDistribution: {},
	};

	return {
		[FlowRole.BLUEPRINT]: scoreBlueprint(bpRs || emptyRs, stats, settings),
		[FlowRole.CAPTURE]: scoreCapture(capRs || emptyRs, stats, settings),
		[FlowRole.TRACK]: scoreTrack(trkRs || emptyRs, stats, settings),
		[FlowRole.FORGE]: scoreForge(frgRs || emptyRs, stats, settings),
		[FlowRole.EXHIBIT]: scoreExhibit(exhRs || emptyRs, stats, settings),
		[FlowRole.VAULT]: scoreVault(undefined, stats, settings),
	};
}

/**
 * FLOW Vault Statistics Collector — v2 (Single-Pass Flat-Index).
 *
 * Design philosophy: Obsidian's metadataCache already indexes every file
 * in memory. We should NEVER do recursive folder walks or async I/O.
 * Instead, we grab the flat file list once and classify each file by
 * its path prefix — exactly how Dataview achieves sub-second queries.
 *
 * Performance target: < 100ms for 10,000+ file vaults.
 */

import { App, TFile, getAllTags } from "obsidian";
import { FlowFolderMap, FlowRole, FlowPluginSettings } from "../../types";

// ── Exported Interfaces ─────────────────────────────────────────────────

export interface RoleStats {
	noteCount: number;
	propertiesGrouped: Record<string, Record<string, number>>;
	tagsCount: Record<string, number>;
	// --- Health Scoring Metrics ---
	notesWithAnyMetadata: number;
	notesWithTags: number;
	notesWithProperties: number;
	notesWithWikilinks: number;
	maxFolderDepth: number;
	subfolderCount: number;
	notesInRoot: number;
	notesPerSubfolder: Record<string, number>;
	// --- Role Specifics ---
	captureHasWikilink: number;
	captureRawNotes: number;
	trackTasksCompleted: number;
	trackTasksPending: number;
	trackHasFeeling: number;
	forgeWipCount: number;
	forgeHeatmap: Record<string, "hot"|"warm"|"cold"|"empty">;
	forgeProgressDistribution: Record<string, number>;
	topLinkedFiles?: Array<{name: string, linkCount: number}>;
}

export interface VaultStats {
	// ── Global Aggregates (Used by main Dashboard charts) ─────────────
	totalActiveNotes: number;
	notesPerFolder: Record<string, number>;
	propertiesGrouped: Record<string, Record<string, number>>;
	tagsCount: Record<string, number>;
	activityTimestamps: number[];
	moodByDate: Record<string, number>;
	feelingCounts: Record<string, number>;
	feelingByDate: Record<string, string[]>;

	// ── Role-specific Telemetry (Used by Flow Progression) ─────────────
	roleStats: Record<string, RoleStats>;

	// ── Vault/Cold Storage Stats ─────────────
	vaultTotalFiles: number;
	vaultTotalSize: number;
	vaultLargestFolders: Array<{name: string, size: number}>;
	orphanedAttachmentsCount: number;
	orphanedAttachmentsSize: number;

	// ── Health Scoring Stats ─────────────
	oversizedFiles: Array<{path: string; size: number; ext: string}>;
	hasGitRepo: boolean;
	captureNoteAges: number[];

	// ── Overall Discipline ─────────────
	namingConventions: {
		zettelkasten: number;
		natural: number;
		kebab: number;
		snake: number;
		camel: number;
		pascal: number;
		other: number;
	};
}

// ── Cache ────────────────────────────────────────────────────────────────

let cachedStats: VaultStats | null = null;

export function invalidateStatsCache(): void {
	cachedStats = null;
}

// ── Helpers ──────────────────────────────────────────────────────────────

export function extractWikilinkName(text: string): string {
	return text.replace(/\[\[(.*?)\]\]/g, (_match, inner) => {
		const parts = inner.split("|");
		if (parts.length > 1) return parts[1].trim();
		const path = parts[0].trim();
		const segments = path.split("/");
		let name = segments[segments.length - 1];
		if (name.toLowerCase().endsWith(".md")) {
			name = name.slice(0, -3);
		}
		return name;
	});
}

/**
 * Determine which FLOW role a file belongs to based on its path.
 * Returns undefined if the file is not inside any FLOW folder.
 */
function classifyFile(filePath: string, folderMap: FlowFolderMap): FlowRole | undefined {
	const lowerPath = filePath.toLowerCase() + "/"; // trailing slash for prefix matching
	for (const role of [FlowRole.CAPTURE, FlowRole.TRACK, FlowRole.FORGE, FlowRole.BLUEPRINT, FlowRole.EXHIBIT]) {
		const folderName = folderMap[role];
		if (!folderName) continue;
		const prefix = folderName.toLowerCase() + "/";
		if (lowerPath.startsWith(prefix) || filePath.startsWith(folderName + "/")) {
			return role;
		}
	}
	return undefined;
}

/**
 * Extract the first sub-folder name inside a Forge directory.
 * e.g. "Forge/ProjectA/file.md" → "ProjectA"
 */
function getForgeSubfolder(filePath: string, forgeFolderName: string): string | undefined {
	const rest = filePath.slice(forgeFolderName.length + 1); // strip "Forge/"
	const slashIdx = rest.indexOf("/");
	if (slashIdx > 0) {
		return rest.slice(0, slashIdx);
	}
	return undefined;
}

// ── Main Collector (SYNCHRONOUS — no async, no recursion) ───────────────

export function collectVaultStats(
	app: App,
	folderMap: FlowFolderMap,
	settings: FlowPluginSettings
): VaultStats {
	if (cachedStats) return cachedStats;

	const now = Date.now();
	const hotLimit = 3 * 24 * 60 * 60 * 1000;   // 3 days
	const warmLimit = 30 * 24 * 60 * 60 * 1000;  // 30 days

	const skipKeys = new Set(["position", "tags", "cssclasses", "aliases", "cssclass"]);

	const stats: VaultStats = {
		propertiesGrouped: {},
		tagsCount: {},
		activityTimestamps: [],
		moodByDate: {},
		feelingCounts: {},
		feelingByDate: {},
		totalActiveNotes: 0,
		notesPerFolder: {},
		roleStats: {},
		vaultTotalFiles: 0,
		vaultTotalSize: 0,
		vaultLargestFolders: [],
		orphanedAttachmentsCount: 0,
		orphanedAttachmentsSize: 0,
		oversizedFiles: [],
		hasGitRepo: false,
		captureNoteAges: [],
		namingConventions: {
			zettelkasten: 0,
			natural: 0,
			kebab: 0,
			snake: 0,
			camel: 0,
			pascal: 0,
			other: 0,
		},
	};

	// Initialize role stats
	const activeRoles = [FlowRole.CAPTURE, FlowRole.TRACK, FlowRole.FORGE, FlowRole.BLUEPRINT, FlowRole.EXHIBIT];
	for (const r of activeRoles) {
		stats.roleStats[r] = {
			noteCount: 0,
			propertiesGrouped: {},
			tagsCount: {},
			notesWithAnyMetadata: 0,
			notesWithTags: 0,
			notesWithProperties: 0,
			notesWithWikilinks: 0,
			maxFolderDepth: 0,
			subfolderCount: 0,
			notesInRoot: 0,
			notesPerSubfolder: {},
			captureHasWikilink: 0,
			captureRawNotes: 0,
			trackTasksCompleted: 0,
			trackTasksPending: 0,
			trackHasFeeling: 0,
			forgeWipCount: 0,
			forgeHeatmap: {},
			forgeProgressDistribution: {},
		};
	}

	// ── PASS 1: ALL files (md + attachments) — single flat loop ──────────

	const allFiles = app.vault.getFiles();
	const folderSizes: Record<string, number> = {};

	// Pre-build incoming link counts (also used for orphan detection)
	const incomingLinkCounts = new Map<string, number>();
	const resolvedLinks = app.metadataCache.resolvedLinks;
	for (const source in resolvedLinks) {
		const targets = resolvedLinks[source];
		if (targets) {
			for (const target in targets) {
				incomingLinkCounts.set(target, (incomingLinkCounts.get(target) || 0) + (targets[target] || 0));
			}
		}
	}

	// Track max mtime per Forge subfolder for heatmap
	const forgeSubfolderMaxMtime: Record<string, number> = {};

	const progressStages = settings.progressLifecycle?.stages || [];
	const wipStages = progressStages.length >= 3 ? new Set(progressStages.slice(1, -1)) : null;

	const blueprintLinks: Array<{name: string, linkCount: number}> = [];

	const vaultFolder = folderMap[FlowRole.VAULT];
	const settingsPath = vaultFolder ? `${vaultFolder}/settings/` : null;

	for (const file of allFiles) {
		// Skip files in the dynamic 'Vault/settings' folder to avoid noise in reports
		if (settingsPath && file.path.startsWith(settingsPath)) continue;

		stats.vaultTotalFiles++;
		stats.vaultTotalSize += file.stat.size;

		// Folder size tracking
		const topFolder = file.path.split("/")[0];
		if (topFolder && topFolder !== file.name) {
			folderSizes[topFolder] = (folderSizes[topFolder] || 0) + file.stat.size;
		}

		// Orphan attachment detection + oversized file tracking
		if (file.extension !== "md" && file.extension !== "canvas") {
			if (!incomingLinkCounts.has(file.path)) {
				stats.orphanedAttachmentsCount++;
				stats.orphanedAttachmentsSize += file.stat.size;
			}
			// Oversized file detection
			const ext = file.extension.toLowerCase();
			const imgExts = new Set(["png", "jpg", "jpeg", "gif", "bmp", "webp", "svg"]);
			const docExts = new Set(["pdf"]);
			if (imgExts.has(ext) && file.stat.size > 2 * 1024 * 1024) {
				stats.oversizedFiles.push({ path: file.path, size: file.stat.size, ext });
			} else if (docExts.has(ext) && file.stat.size > 5 * 1024 * 1024) {
				stats.oversizedFiles.push({ path: file.path, size: file.stat.size, ext });
			}
			continue;
		}

		// Skip non-.md files from here
		if (file.extension !== "md") continue;

		// Classify into FLOW role (delayed so we can extract global metrics first)

		// ── GLOBAL MOOD & FEELING TRACKING ──
		const preCache = app.metadataCache.getFileCache(file);
		if (preCache?.frontmatter) {
			const fmRaw = preCache.frontmatter;
			const moodKey = Object.keys(fmRaw).find(k => k.toLowerCase() === "mood");
			const rawMood = moodKey ? fmRaw[moodKey] : undefined;

			const feelingKey = Object.keys(fmRaw).find(k => k.toLowerCase() === "feeling" || k.toLowerCase() === "feelings");
			const rawFeeling = feelingKey ? fmRaw[feelingKey] : undefined;

			if (rawMood !== undefined && rawMood !== null) {
				const moodNum = Number(rawMood);
				if (!isNaN(moodNum)) {
					const dateMatch = file.basename.match(/\d{4}-\d{2}-\d{2}/);
					const dStr = dateMatch ? dateMatch[0] : (new Date(file.stat.ctime).toISOString().split("T")[0] as string);
					stats.moodByDate[dStr] = moodNum;
				}
			}
			if (rawFeeling !== undefined && rawFeeling !== null) {
				const feelings: string[] = Array.isArray(rawFeeling) ? rawFeeling : [String(rawFeeling)];
				const fdMatch = file.basename.match(/\d{4}-\d{2}-\d{2}/);
				const fDate = fdMatch ? fdMatch[0] : (new Date(file.stat.ctime).toISOString().split("T")[0] as string);
				for (const f of feelings) {
					const text = String(f).trim().toLowerCase();
					if (text) {
						stats.feelingCounts[text] = (stats.feelingCounts[text] || 0) + 1;
						if (!stats.feelingByDate[fDate]) stats.feelingByDate[fDate] = [];
						stats.feelingByDate[fDate].push(text);
					}
				}
			}
		}

		const role = classifyFile(file.path, folderMap);
		if (!role) continue; // Not a FLOW file

		// Skip TOC files
		if (file.name === "0. TOC.md") continue;

		const rs = stats.roleStats[role];
		if (!rs) continue;

		// Blueprint top links tracking
		if (role === FlowRole.BLUEPRINT) {
			const count = incomingLinkCounts.get(file.path) || 0;
			blueprintLinks.push({ name: file.basename, linkCount: count });
		}

		stats.totalActiveNotes++;
		stats.notesPerFolder[role] = (stats.notesPerFolder[role] || 0) + 1;
		rs.noteCount++;

		// Analyze naming convention
		const baseName = file.basename;
		if (/^\d{2,}(?:\.\d+)?[\s\-_]/.test(baseName) || /^\d{12,}/.test(baseName)) {
			stats.namingConventions.zettelkasten++; // Zettelkasten UID or Johnny.Decimal
		} else if (baseName.includes(" ")) {
			stats.namingConventions.natural++;
		} else if (baseName.includes("-") && baseName.toLowerCase() === baseName) {
			stats.namingConventions.kebab++;
		} else if (baseName.includes("_") && baseName.toLowerCase() === baseName) {
			stats.namingConventions.snake++;
		} else if (/^[a-z]+[A-Z][a-zA-Z]*$/.test(baseName)) {
			stats.namingConventions.camel++;
		} else if (/^[A-Z][a-zA-Z]*$/.test(baseName)) {
			stats.namingConventions.pascal++;
		} else {
			stats.namingConventions.other++;
		}

		// ── Folder depth + organization tracking ──
		const roleFolder = folderMap[role];
		const relPath = file.path.slice(roleFolder.length + 1); // strip "RoleFolder/"
		const segments = relPath.split("/");
		const depth = segments.length - 1; // 0 = root of role folder
		if (depth > rs.maxFolderDepth) rs.maxFolderDepth = depth;
		if (depth === 0) {
			rs.notesInRoot++;
		} else {
			const firstSub = segments[0] || "";
			rs.notesPerSubfolder[firstSub] = (rs.notesPerSubfolder[firstSub] || 0) + 1;
		}

		// ── Activity timestamps ──
		stats.activityTimestamps.push(file.stat.ctime);
		if (file.stat.ctime !== file.stat.mtime) {
			stats.activityTimestamps.push(file.stat.mtime);
		}

		// ── Forge Heatmap: track max mtime per subfolder ──
		if (role === FlowRole.FORGE) {
			const sub = getForgeSubfolder(file.path, folderMap[FlowRole.FORGE]);
			if (sub) {
				const prev = forgeSubfolderMaxMtime[sub] || 0;
				if (file.stat.mtime > prev) {
					forgeSubfolderMaxMtime[sub] = file.stat.mtime;
				}
			}
		}

		// ── Metadata from cache (instant — already in memory) ──
		const cache = app.metadataCache.getFileCache(file);
		let isRaw = true;

		if (cache) {
			// ── Track per-note metadata presence ──
			const hasWikilinks = !!(cache.links && cache.links.length > 0);
			const tags = getAllTags(cache) || [];
			const hasTags = tags.length > 0;
			let hasProperties = false;

			// Capture wikilinks (any role)
			if (hasWikilinks) {
				rs.notesWithWikilinks++;
				if (role === FlowRole.CAPTURE) rs.captureHasWikilink++;
			}
			if (hasTags) rs.notesWithTags++;

			// Track tasks
			if (role === FlowRole.TRACK && cache.listItems) {
				for (const li of cache.listItems) {
					if (li.task !== undefined && li.task !== null) {
						if (li.task === " " || li.task === "") rs.trackTasksPending++;
						else rs.trackTasksCompleted++;
					}
				}
			}

			if (cache.frontmatter) {
				const fm = cache.frontmatter;

				// Raw detection
				const meaningfulKeys = Object.keys(fm).filter(k => k !== "position" && k !== "cssclasses");
				if (meaningfulKeys.length > 0) {
					isRaw = false;
					hasProperties = true;
					rs.notesWithProperties++;
				}

				// Forge WIP + progress distribution
				if (role === FlowRole.FORGE && fm.progress) {
					const pVal = String(fm.progress).toLowerCase();
					rs.forgeProgressDistribution[pVal] = (rs.forgeProgressDistribution[pVal] || 0) + 1;
					if (wipStages) {
						if (wipStages.has(fm.progress)) rs.forgeWipCount++;
					} else {
						if (!["raw", "done", "archived", "completed"].includes(pVal)) {
							rs.forgeWipCount++;
						}
					}
				}

				// Tags
				const tags = getAllTags(cache) || [];
				for (const tag of tags) {
					const cleanTag = tag.replace(/^#/, "");
					stats.tagsCount[cleanTag] = (stats.tagsCount[cleanTag] || 0) + 1;
					rs.tagsCount[cleanTag] = (rs.tagsCount[cleanTag] || 0) + 1;
				}

				// Properties
				for (const [key, value] of Object.entries(fm)) {
					if (skipKeys.has(key)) continue;
					if (value === null || value === undefined) continue;

					const values = Array.isArray(value) ? value : [value];
					for (const val of values) {
						if (typeof val === "object" && val !== null) continue;
						const valStr = extractWikilinkName(String(val).trim());
						if (valStr === "") continue;

						if (!stats.propertiesGrouped[key]) stats.propertiesGrouped[key] = {};
						stats.propertiesGrouped[key][valStr] = (stats.propertiesGrouped[key][valStr] || 0) + 1;

						if (!rs.propertiesGrouped[key]) rs.propertiesGrouped[key] = {};
						rs.propertiesGrouped[key][valStr] = (rs.propertiesGrouped[key][valStr] || 0) + 1;
					}
				}

				// Track Vault Health (Journaling score)
				const feelingKey = Object.keys(fm).find(k => k.toLowerCase() === "feeling" || k.toLowerCase() === "feelings");
				if (feelingKey && fm[feelingKey] !== undefined && fm[feelingKey] !== null) {
					if (role === FlowRole.TRACK) rs.trackHasFeeling++;
				}
			}

			// ── Aggregate per-note metadata presence ──
			if (hasWikilinks || hasTags || hasProperties) {
				rs.notesWithAnyMetadata++;
			}

			// Capture raw check
			if (role === FlowRole.CAPTURE && isRaw) {
				rs.captureRawNotes++;
			}

			// Capture note age tracking
			if (role === FlowRole.CAPTURE) {
				const ageDays = (now - file.stat.ctime) / (24 * 60 * 60 * 1000);
				stats.captureNoteAges.push(ageDays);
			}
		}
	}

	// ── POST-PROCESSING (all synchronous, trivial cost) ─────────────────

	// Build Top 5 Blueprint Linked
	const blueprintRs = stats.roleStats[FlowRole.BLUEPRINT];
	if (blueprintRs) {
		blueprintLinks.sort((a, b) => b.linkCount - a.linkCount);
		blueprintRs.topLinkedFiles = blueprintLinks.slice(0, 5);
	}

	// Build Forge heatmap from collected mtime data
	const forgeRs = stats.roleStats[FlowRole.FORGE];
	if (forgeRs) {
		for (const [subName, maxMtime] of Object.entries(forgeSubfolderMaxMtime)) {
			const diff = now - maxMtime;
			if (diff <= hotLimit) forgeRs.forgeHeatmap[subName] = "hot";
			else if (diff <= warmLimit) forgeRs.forgeHeatmap[subName] = "warm";
			else forgeRs.forgeHeatmap[subName] = "cold";
		}
	}

	// Compute subfolder counts for all roles
	for (const role of activeRoles) {
		const rs = stats.roleStats[role];
		if (rs) {
			rs.subfolderCount = Object.keys(rs.notesPerSubfolder).length;
		}
	}

	// Detect git repo
	const gitFolder = app.vault.getAbstractFileByPath(".git");
	stats.hasGitRepo = !!gitFolder;

	// Sort mood dates
	const sortedMood: Record<string, number> = {};
	Object.keys(stats.moodByDate).sort().forEach((date) => {
		const val = stats.moodByDate[date];
		if (val !== undefined) {
			sortedMood[date] = val;
		}
	});
	stats.moodByDate = sortedMood;

	// Largest folders
	const sortedFolders = Object.keys(folderSizes)
		.map(name => ({ name, size: folderSizes[name] || 0 }))
		.sort((a, b) => b.size - a.size);
	stats.vaultLargestFolders = sortedFolders.slice(0, 5);

	cachedStats = stats;
	return stats;
}

import { App, setIcon } from "obsidian";
