				tbody.empty();

				const lowerQuery = this.navigatorSearchQuery.toLowerCase();
				const resolvedLinks = this.app.metadataCache.resolvedLinks;
				incomingFiles.clear();
				for (const src in resolvedLinks) {
					for (const tgt in resolvedLinks[src]) {
						if (!incomingFiles.has(tgt)) incomingFiles.set(tgt, []);
						const srcFile = this.app.vault.getAbstractFileByPath(src);
						if (srcFile && (srcFile as unknown).extension === "md") {
							incomingFiles.get(tgt)!.push(srcFile as import("obsidian").TFile);
						}
					}
				}

				let sourceFiles: unknown[];
				if (isAttachmentMode) {
					sourceFiles = allVaultFiles;
				} else if (isTagHealthMode || isPropHealthMode) {
					sourceFiles = [];
					let tagCounts: Record<string, import("obsidian").TFile[]> = {};
					let propCounts: Record<string, { file: import("obsidian").TFile, values: unknown }[]> = {};

					for (const f of mdFiles) {
						const c = this.app.metadataCache.getFileCache(f);
						if (!c) continue;

						if (isTagHealthMode) {
							const tags = c.tags ? c.tags.map(t => t.tag.replace(/^#/, "")) : (c.frontmatter?.tags ? [c.frontmatter.tags].flat().map(t => String(t).replace(/^#/, "")) : []);
							for (const t of tags) {
								if (t) {
									if (!tagCounts[t]) tagCounts[t] = [];
									tagCounts[t].push(f);
								}
							}
						}

						if (isPropHealthMode) {
							const keys = c.frontmatter ? Object.keys(c.frontmatter).filter(k => k !== "position" && k !== "cssclasses") : [];
							for (const k of keys) {
								if (!propCounts[k]) propCounts[k] = [];
								propCounts[k].push({ file: f, values: c.frontmatter![k] });
							}
						}
					}

					if (isTagHealthMode) {
						for (const [tag, files] of Object.entries(tagCounts)) {
							// Global checking: only 1 file in the whole vault
							if (files.length === 1) {
								sourceFiles.push({
									isOrphanItem: true,
									path: `tag:${tag}`,
									basename: tag,
									file: files[0]!,
									stat: files[0]!.stat,
									parent: files[0]!.parent,
									extension: files[0]!.extension
								});
							}
						}
					} else if (isPropHealthMode) {
						for (const [prop, files] of Object.entries(propCounts)) {
							if (files.length === 1) {
								sourceFiles.push({
									isOrphanItem: true,
									path: `prop:${prop}`,
									basename: prop,
									file: files[0]!.file,
									values: files[0]!.values,
									stat: files[0]!.file.stat,
									parent: files[0]!.file.parent,
									extension: files[0]!.file.extension
								});
							}
						}
					}
				} else {
					sourceFiles = mdFiles.slice();
				}

				let filteredFiles = sourceFiles.filter(f => {
					if (lowerQuery) {
						const matchQuery = f.basename.toLowerCase().includes(lowerQuery) || (f.parent?.path || "").toLowerCase().includes(lowerQuery);
						if (!matchQuery) return false;
					}

					if (this.navigatorActiveFilters.length > 0) {
						const cache = this.app.metadataCache.getFileCache(f.isOrphanItem ? f.file : f);
						const fm = cache?.frontmatter;
						const now = Date.now();
						const typedFilters: Record<string, string[]> = {};

						for (const filter of this.navigatorActiveFilters) {
							if (!typedFilters[filter.type]) typedFilters[filter.type] = [];
							typedFilters[filter.type]!.push(filter.value);
						}

						for (const [fType, fValues] of Object.entries(typedFilters)) {
							let typeMatch = false;

							for (const val of fValues) {
								let valMatch = false;

								if (fType === "folder") {
									const folderName = this.settings.folderMap[val as FlowRole];
									if (folderName) {
										const cleanActiveFolder = folderName.replace(/^\d+\.\s*/, "").trim().toLowerCase();
										const NotePath = (f.isOrphanItem ? f.file.parent?.path : f.parent?.path) || "";
										const cleanFolderPath = NotePath.replace(/^\d+\.\s*/, "").trim().toLowerCase();
										valMatch = cleanFolderPath.startsWith(cleanActiveFolder);
									}
								} else if (fType === "task") {
									if (val === "todo") valMatch = cache?.listItems?.some((li: unknown) => li.task !== undefined && li.task === " ") ?? false;
									else if (val === "done") valMatch = cache?.listItems?.some((li: unknown) => li.task !== undefined && li.task !== " ") ?? false;
								} else if (fType === "eisenhower") {
									const urgencyField = this.settings.urgencyConfig?.fieldName || "urgency";
									const impactField = this.settings.impactConfig?.fieldName || "impact";
									const urgencyVal = Number(fm?.[urgencyField]) || 0;
									const impactVal = Number(fm?.[impactField]) || 0;
									const urgencyLevels = this.settings.urgencyConfig?.levels || [];
									const impactLevels = this.settings.impactConfig?.levels || [];
									const urgencyHigh = urgencyLevels.length > 0 ? urgencyVal >= (urgencyLevels[Math.floor(urgencyLevels.length / 2)]?.value ?? 3) : urgencyVal >= 3;
									const impactHigh = impactLevels.length > 0 ? impactVal >= (impactLevels[Math.floor(impactLevels.length / 2)]?.value ?? 3) : impactVal >= 3;
									if (val === "p1") valMatch = urgencyHigh && impactHigh;
									else if (val === "p2") valMatch = impactHigh && !urgencyHigh;
									else if (val === "p3") valMatch = urgencyHigh && !impactHigh;
									else if (val === "p4") valMatch = !urgencyHigh && !impactHigh;

								} else if (fType === "temperature") {
									const ageDays = (now - (f.isOrphanItem ? f.file.stat.mtime : f.stat.mtime)) / (24 * 60 * 60 * 1000);
									if (val === "hot") valMatch = ageDays < 3;
									else if (val === "warm") valMatch = ageDays >= 3 && ageDays <= 30;
									else if (val === "cold") valMatch = ageDays > 30;

								} else if (fType === "channel") {
									const chField = this.settings.channelFieldName || "channel";
									const chVal = fm?.[chField];
									if (chVal) {
										const channels = Array.isArray(chVal) ? chVal.flatMap(v => String(v).split(",").map(s => s.trim().toLowerCase())) : String(chVal).split(",").map(c => c.trim().toLowerCase());
										valMatch = channels.includes(val.toLowerCase());
									}

								} else if (fType === "publish") {
									const pubField = this.settings.publishFieldName || "publish";
									const pubVal = fm?.[pubField];
									if (!pubVal && val === "later") valMatch = true;
									else if (pubVal) {
										const pubDate = new Date(String(pubVal)).getTime();
										if (!isNaN(pubDate)) {
											const diffDays = (pubDate - now) / (86400000);
											if (val === "today") valMatch = diffDays >= 0 && diffDays <= 1;
											else if (val === "3days") valMatch = diffDays >= 0 && diffDays <= 3;
											else if (val === "7days") valMatch = diffDays >= 0 && diffDays <= 7;
											else if (val === "2weeks") valMatch = diffDays >= 0 && diffDays <= 14;
											else if (val === "later") valMatch = diffDays > 14;
										}
									}

								} else if (fType === "feeling") {
									const feelVal = fm?.feeling;
									if (feelVal) {
										const feelings = Array.isArray(feelVal) ? feelVal.map((v: unknown) => String(v).toLowerCase()) : [String(feelVal).toLowerCase()];
										valMatch = feelings.includes(val.toLowerCase());
									}

								} else if (fType === "vault-health") {
									if (val === "orphan-notes") {
										valMatch = (incomingFiles.get(f.path)?.length || 0) === 0;
									} else if (val === "no-properties") {
										const meaningfulKeys = fm ? Object.keys(fm).filter(k => k !== "position" && k !== "cssclasses") : [];
										valMatch = meaningfulKeys.length === 0;
									} else if (val === "no-tags") {
										const allTags = cache?.tags?.length ? cache.tags : (fm?.tags ? [fm.tags].flat() : []);
										valMatch = allTags.length === 0;
									} else if (val === "single-tag") {
										valMatch = !!f.isOrphanItem;
									} else if (val === "single-property") {
										valMatch = !!f.isOrphanItem;
									}

								} else if (fType === "attachment") {
									const sizeMB = f.stat.size / (1024 * 1024);
									if (val === "size-10mb") valMatch = sizeMB > 10;
									else if (val === "size-5mb") valMatch = sizeMB > 5;
									else if (val === "size-2mb") valMatch = sizeMB > 2;
									else if (val === "size-1mb") valMatch = sizeMB > 1;
									else if (val.startsWith("type-")) {
										const expectedType = val.slice(5);
										const fileType = extTypeMap[f.extension.toLowerCase()] || "other";
										valMatch = fileType === expectedType;
									}
								}

								if (valMatch) {
									typeMatch = true;
									break; // OR logic within same group
								}
							}

							if (!typeMatch) {
								return false; // AND logic between different groups
							}
						}
					}
					return true;
				});

				const dir = this.navigatorSortAsc ? 1 : -1;
				filteredFiles.sort((a, b) => {
					if (this.navigatorSortCol === 0) return 0;
					const va = getValString(a, this.navigatorSortCol);
					const vb = getValString(b, this.navigatorSortCol);
					return dir * va.localeCompare(vb);
				});

				const totalPages = Math.ceil(filteredFiles.length / this.navigatorPageSize) || 1;
				if (this.navigatorCurrentPage > totalPages) this.navigatorCurrentPage = totalPages;

				pageInfo.setText(`Page ${this.navigatorCurrentPage} of ${totalPages}`);

				const startIdx = (this.navigatorCurrentPage - 1) * this.navigatorPageSize;
				const displayFiles = filteredFiles.slice(startIdx, startIdx + this.navigatorPageSize);

				if (selectAllCb) {
					const pagePaths = displayFiles.map(f => f.path);
					const allSelected = pagePaths.length > 0 && pagePaths.every(p => this.navigatorSelectedFiles.has(p));
					selectAllCb.checked = allSelected;
					selectAllCb.indeterminate = !allSelected && pagePaths.some(p => this.navigatorSelectedFiles.has(p));
					selectAllCb.onchange = () => {
						if (selectAllCb!.checked) {
							pagePaths.forEach(p => this.navigatorSelectedFiles.add(p));
						} else {
							pagePaths.forEach(p => this.navigatorSelectedFiles.delete(p));
						}
						updateQABar();
						triggerRenderRows();
					};
				}

				displayFiles.forEach((file, displayIdx) => {
					const rowIdx = startIdx + displayIdx + 1;
					const tr = tbody.createEl("tr");
					tr.setCssProps({ "border-bottom": "1px solid var(--background-modifier-border-hover)" })
					const isChecked = this.navigatorSelectedFiles.has(file.path);
					if (isChecked) tr.setCssProps({ "background-color": "var(--background-modifier-active-hover)" })

					const stripeBg = "rgba(128, 128, 128, 0.08)";
					if (!isChecked && this.navigatorStripedRows && displayIdx % 2 === 1) {
						tr.setCssProps({ "background-color": stripeBg })
					}

					tr.onmouseenter = () => {
						if (!this.navigatorSelectedFiles.has(file.path)) tr.setCssProps({ "background-color": "var(--background-modifier-hover)" })
					};
					tr.onmouseleave = () => {
						if (this.navigatorSelectedFiles.has(file.path)) {
							tr.setCssProps({ "background-color": "var(--background-modifier-active-hover)" })
						} else {
							tr.setCssProps({ "background-color": (this.navigatorStripedRows && displayIdx % 2 === 1) ? stripeBg : "transparent" })
						}
					};

					const cache = this.app.metadataCache.getFileCache(file);

					if (isAttachmentMode) {
						const tdCb = tr.createEl("td"); tdCb.setCssProps({ "padding": "4px 6px" })
						const cb = tdCb.createEl("input", { type: "checkbox" });
						cb.checked = this.navigatorSelectedFiles.has(file.path);
						cb.onchange = () => {
							if (cb.checked) this.navigatorSelectedFiles.add(file.path);
							else this.navigatorSelectedFiles.delete(file.path);
							updateQABar();
							triggerRenderRows();
						};

						const tdIdx = tr.createEl("td"); tdIdx.setCssProps({ "padding": "6px 8px", "color": "var(--text-faint)", "font-size": "0.85em" })
						tdIdx.setText(String(rowIdx));

						const tdName = tr.createEl("td"); tdName.setCssProps({ "padding": "6px 8px" })
						tdName.createEl("span", { text: file.basename + "." + file.extension });

						const tdFolder = tr.createEl("td"); tdFolder.setCssProps({ "padding": "6px 8px", "color": "var(--text-muted)", "font-size": "0.85em" })
						tdFolder.setText(file.parent?.path || "/");

						const fileSizeMB = file.stat.size / (1024 * 1024);
						const sizeText = fileSizeMB >= 1 ? `${fileSizeMB.toFixed(1)} MB` : `${(file.stat.size / 1024).toFixed(0)} KB`;
						const tdSize = tr.createEl("td"); tdSize.setCssProps({ "padding": "6px 8px", "font-size": "0.85em", "text-align": "right" })
						tdSize.setText(sizeText);
						if (fileSizeMB > 10) tdSize.setCssProps({ "color": "var(--text-error)" })
						else if (fileSizeMB > 2) tdSize.setCssProps({ "color": "var(--color-orange)" })

						const fileType = extTypeMap[file.extension.toLowerCase()] || "other";
						const tdType = tr.createEl("td"); tdType.setCssProps({ "padding": "6px 8px", "font-size": "0.82em", "color": "var(--text-accent)" })
						tdType.setText(file.extension.toLowerCase());

						const incomingForFile = incomingFiles.get(file.path) || [];

						const tdLinks = tr.createEl("td"); tdLinks.setCssProps({ "padding": "6px 8px", "font-size": "0.85em", "text-align": "center" })
						tdLinks.setText(String(incomingForFile.length));

						const tdLinkedFiles = tr.createEl("td"); tdLinkedFiles.setCssProps({ "padding": "6px 8px", "font-size": "0.85em" })
						if (incomingForFile.length > 0) {
							const linkContainer = tdLinkedFiles.createDiv();
							linkContainer.setCssProps({ "display": "flex", "flex-wrap": "wrap", "gap": "4px" })
							incomingForFile.forEach(srcFile => {
								const pill = linkContainer.createSpan();
								pill.setCssProps({ "padding": "2px 6px", "border-radius": "4px", "background-color": "var(--background-modifier-active-hover)", "color": "var(--text-accent)", "cursor": "pointer", "font-size": "0.9em" })
								pill.setText(srcFile.basename);
								pill.title = srcFile.path;
								pill.onclick = (e) => {
									e.stopPropagation();
									this.app.workspace.getLeaf(false).openFile(srcFile);
								};
							});
						}

						const tdMod = tr.createEl("td"); tdMod.setCssProps({ "padding": "6px 8px", "color": "var(--text-faint)", "font-size": "0.85em" })
						tdMod.setText(new Date(file.stat.mtime).toISOString().split("T")[0] || "");
					} else if (isTagHealthMode || isPropHealthMode) {
						const tdCb = tr.createEl("td"); tdCb.setCssProps({ "padding": "4px 6px" })
						const cb = tdCb.createEl("input", { type: "checkbox" });
						cb.checked = this.navigatorSelectedFiles.has(file.path);
						cb.onchange = () => {
							if (cb.checked) this.navigatorSelectedFiles.add(file.path);
							else this.navigatorSelectedFiles.delete(file.path);
							updateQABar();
							triggerRenderRows();
						};

						const tdIdx = tr.createEl("td"); tdIdx.setCssProps({ "padding": "6px 8px", "color": "var(--text-faint)", "font-size": "0.85em" })
						tdIdx.setText(String(rowIdx));

						const tdName = tr.createEl("td"); tdName.setCssProps({ "padding": "6px 8px" })
						const pill = tdName.createSpan();
						pill.setCssProps({ "padding": "2px 8px", "border-radius": "12px", "background-color": "var(--background-modifier-active-hover)", "color": "var(--interactive-accent)", "font-weight": "600", "font-size": "0.85em" })
						pill.setText(isTagHealthMode ? `#${file.basename}` : file.basename);

						const tdNote = tr.createEl("td"); tdNote.setCssProps({ "padding": "6px 8px", "font-size": "0.85em" })
						const noteLink = tdNote.createSpan();
						noteLink.setCssProps({ "color": "var(--text-accent)", "cursor": "pointer", "text-decoration": "underline" })
						noteLink.setText(file.file.basename);
						noteLink.onclick = (e) => {
							e.stopPropagation();
							this.app.workspace.getLeaf(false).openFile(file.file);
						};

						if (isPropHealthMode) {
							const tdVals = tr.createEl("td"); tdVals.setCssProps({ "padding": "6px 8px", "font-size": "0.85em", "color": "var(--text-muted)", "word-break": "break-all" })
							tdVals.setText(String(file.values || ""));
						}
					} else {
						const tdCb = tr.createEl("td"); tdCb.setCssProps({ "padding": "4px 6px" })
						const cb = tdCb.createEl("input", { type: "checkbox" });
						cb.checked = this.navigatorSelectedFiles.has(file.path);
						cb.onchange = () => {
							if (cb.checked) this.navigatorSelectedFiles.add(file.path);
							else this.navigatorSelectedFiles.delete(file.path);
							updateQABar();
							triggerRenderRows();
						};

						allColNames.forEach((colName, colIdx) => {
							if (!this.navigatorVisibleCols[colIdx]) return;

							const td = tr.createEl("td");
							td.addClass("flow-nav-td");
							const lowerCol = colName.toLowerCase();

							if (lowerCol === "#") {
								td.setText(String(rowIdx));
								td.addClass("flow-nav-td-faint");
							} else if (lowerCol === "name") {
								const link = td.createEl("a", { text: file.basename });
								link.addClass("flow-nav-link-cursor");
								link.onclick = (e) => { e.preventDefault(); this.app.workspace.getLeaf(false).openFile(file); this.closeModal(); };
							} else if (lowerCol === "folder") {
								td.setText(file.parent?.path || "/");
								td.addClass("flow-nav-td-muted");
							} else if (lowerCol === "created") {
								td.setText(new Date(file.stat.ctime).toISOString().split("T")[0] || "");
								td.addClass("flow-nav-td-faint");
							} else if (lowerCol === "modified") {
								td.setText(new Date(file.stat.mtime).toISOString().split("T")[0] || "");
								td.addClass("flow-nav-td-faint");
							} else if (lowerCol === "tags") {
								let tagsText = "";
								if (cache?.tags) tagsText = cache.tags.map(t => t.tag).join(", ");
								else if (cache?.frontmatter?.tags) {
									const fmTags = cache.frontmatter.tags;
									tagsText = Array.isArray(fmTags) ? fmTags.join(", ") : String(fmTags);
								}
								td.setText(tagsText || "-");
								td.addClass("flow-nav-td-accent");
							} else {
								let valText = "-";
								const readProp = (propValue: unknown) => {
									return Array.isArray(propValue) ? propValue.map(v => extractWikilinkName(String(v))).join(", ") : extractWikilinkName(String(propValue));
								};
								if (cache?.frontmatter && cache.frontmatter[lowerCol] !== undefined) {
									valText = readProp(cache.frontmatter[lowerCol]);
								} else if (cache?.frontmatter && cache.frontmatter[colName] !== undefined) {
									valText = readProp(cache.frontmatter[colName]);
								}
								td.setText(valText);
								td.addClass("flow-nav-td-small");
							}
						});
					}
				});

				if (displayFiles.length === 0) {
					const tr = tbody.createEl("tr");
					const td = tr.createEl("td", { text: isVi ? "Không tìm thấy file nào." : "No files found." });
					td.colSpan = activeColNames.length;
					td.addClass("flow-dashboard-ui-50");
				}
			};

			searchInput.oninput = (e) => {
				this.navigatorSearchQuery = (e.target as HTMLInputElement).value;
				this.navigatorCurrentPage = 1;
				triggerRenderRows();
			};

			prevBtn.onclick = () => {
				if (this.navigatorCurrentPage > 1) {
					this.navigatorCurrentPage--;
					triggerRenderRows();
				}
			};

			nextBtn.onclick = () => {
				this.navigatorCurrentPage++;
				triggerRenderRows();
			};

			triggerRenderRows();
		};

		triggerRenderTable();
	}
}

import { App, setIcon } from "obsidian";
import type * as echartsCore from "echarts/core";
import type { EChartsOption } from "echarts";
import { FlowPluginSettings } from "../../../types";
import { VaultStats, extractWikilinkName } from "../stats-collector";
import { CHART_PALETTE, WARM_CHART_PALETTE, HEATMAP_RAMP, ACTIVITY_COLOR, ACTIVITY_AREA, ACTIVITY_AVGLINE, FEELING_PALETTE, BRAND } from "../../../brand-colors";

type DashboardTab = "properties" | "tags" | "activity" | "mood";

export class StatisticsView {
	private chartInstanceLeft: echartsCore.EChartsType | null = null;
	private chartInstanceRight: echartsCore.EChartsType | null = null;
	private chartInstanceSingle: echartsCore.EChartsType | null = null;
	private chartInstances: echartsCore.EChartsType[] = [];

	private selectedPropertyCategory: string | null = null;
	private excludedProperties: Set<string> = new Set(["created", "summary", "publish_url", "mindmap-plugin", "min-impact", "created-after"]);

	constructor(
		private app: App,
		private settings: FlowPluginSettings,
		private container: HTMLElement,
		private echartsModule: typeof echartsCore
	) { }

	public destroy() {
		for (const chart of this.chartInstances) {
			chart.dispose();
		}
		this.chartInstances = [];
		this.chartInstanceSingle = null;
		this.chartInstanceLeft = null;
		this.chartInstanceRight = null;
	}

	public resize() {
		for (const chart of this.chartInstances) {
			chart.resize();
		}
	}

	public render(stats: VaultStats, activeTab: DashboardTab) {
		this.destroy();
		this.container.empty();

		const theme = "light";

		if (activeTab === "properties") {
			const configBar = this.container.createDiv();
			configBar.addClass("flow-dashboard-ui-6");
			const isVi = this.settings.language === "vi";
			const configBtn = configBar.createEl("button");
			configBtn.addClass("flow-dashboard-ui-7");
			configBtn.title = isVi ? "Lọc thuộc tính" : "Filter properties";

			const iconSpan = configBtn.createSpan();
			setIcon(iconSpan, "settings");
			iconSpan.addClass("flow-dashboard-ui-8");
			configBtn.createSpan({ text: isVi ? "Lọc thuộc tính" : "Filter Props", cls: "flow-filter-props-text" });

			configBtn.onclick = () => {
				let popup = this.container.querySelector(".flow-prop-filter-popup") as HTMLElement;
				if (popup) { popup.remove(); return; }

				popup = this.container.createDiv("flow-prop-filter-popup");
				popup.addClass("flow-dashboard-ui-9");

				popup.createEl("div", { text: isVi ? "Loại trừ thuộc tính:" : "Exclude Properties:", cls: "flow-dashboard-fontweight-600" });

				const allKeys = Object.keys(stats.propertiesGrouped).sort();
				for (const key of allKeys) {
					const row = popup.createDiv();
					row.addClass("flow-dashboard-ui-10");

					const cb = row.createEl("input", { type: "checkbox" });
					cb.checked = !this.excludedProperties.has(key);
					row.createEl("label", { text: key });

					cb.onchange = () => {
						if (cb.checked) this.excludedProperties.delete(key);
						else this.excludedProperties.add(key);
						this.render(stats, activeTab);
					};
				}

				setTimeout(() => {
					const handler = (e: MouseEvent) => {
						if (popup && !popup.contains(e.target as Node) && e.target !== configBtn) {
							popup.remove();
							document.removeEventListener("click", handler);
						}
					};
					document.addEventListener("click", handler);
				}, 0);
			};

			this.container.addClass("flow-stats-container-relative");

			// Dedicated flex container for the two charts (separate from configBar)
			const chartsRow = this.container.createDiv();
			const isMobileView = window.innerWidth <= 768;

			const leftDiv = chartsRow.createDiv();
			if (isMobileView) {
				chartsRow.addClass("flow-stats-charts-row-col");
				leftDiv.addClass("flow-dashboard-ui-11");
			} else {
				chartsRow.addClass("flow-stats-charts-row");
				leftDiv.addClass("flow-dashboard-ui-12");
			}

			const rightDiv = chartsRow.createDiv();
			if (isMobileView) rightDiv.addClass("flow-dashboard-ui-13");
			else rightDiv.addClass("flow-dashboard-ui-14");

			this.chartInstanceLeft = this.echartsModule.init(leftDiv, theme);
			this.chartInstanceRight = this.echartsModule.init(rightDiv, theme);
			if (this.chartInstanceLeft) this.chartInstances.push(this.chartInstanceLeft);
			if (this.chartInstanceRight) this.chartInstances.push(this.chartInstanceRight);

			this.renderPropertiesInteractive(stats);

		} else if (activeTab === "activity") {
			this.container.addClass("flow-stats-container-relative");
			this.container.addClass("flow-stats-flex-col");

			const topDiv = this.container.createDiv();
			topDiv.addClass("flow-dashboard-ui-15");

			const bottomDiv = this.container.createDiv();
			bottomDiv.addClass("flow-dashboard-ui-16");

			this.chartInstanceLeft = this.echartsModule.init(topDiv, theme);
			this.chartInstanceRight = this.echartsModule.init(bottomDiv, theme);
			if (this.chartInstanceLeft) this.chartInstances.push(this.chartInstanceLeft);
			if (this.chartInstanceRight) this.chartInstances.push(this.chartInstanceRight);

			const heatmapOption = this.getActivityChartOption(stats);
			if (heatmapOption.calendar) {
				const numYears = Array.isArray(heatmapOption.calendar) ? heatmapOption.calendar.length : 1;
				topDiv.setCssProps({ "min-height": (numYears * 180 + 140) + "px" })
			}
			heatmapOption.backgroundColor = "transparent";
			this.chartInstanceLeft?.setOption(heatmapOption, true);

			const dowOption = this.getActivityByDayOfWeekOption(stats);
			dowOption.backgroundColor = "transparent";
			this.chartInstanceRight?.setOption(dowOption, true);

			setTimeout(() => {
				this.chartInstanceLeft?.resize();
				this.chartInstanceRight?.resize();
			}, 100);

		} else {
			const singleDiv = this.container.createDiv();
			singleDiv.addClass("flow-stats-single-chart");

			this.chartInstanceSingle = this.echartsModule.init(singleDiv, theme);
			if (this.chartInstanceSingle) this.chartInstances.push(this.chartInstanceSingle);

			let option: EChartsOption = {};
			switch (activeTab) {
				case "tags": option = this.getTagsChartOption(stats); break;
				case "mood": option = this.getMoodChartOption(stats); break;
			}
			option.backgroundColor = "transparent";
			this.chartInstanceSingle?.setOption(option, true);
		}
	}

	private renderPropertiesInteractive(stats: VaultStats) {
		if (!this.chartInstanceLeft || !this.chartInstanceRight) return;

		const propKeys = Object.keys(stats.propertiesGrouped)
			.filter(k => !this.excludedProperties.has(k));

		const treemapData = propKeys.map(key => {
			const group = stats.propertiesGrouped[key];
			const totalCount = Object.values(group || {}).reduce((a, b) => a + b, 0);
			return { name: key, value: totalCount };
		}).sort((a, b) => b.value - a.value).slice(0, 50);

		const leftOption: EChartsOption = {
			backgroundColor: "transparent",
			title: { text: this.settings.language === "vi" ? "Thuộc tính (Nhấn vào biểu đồ để xem chi tiết)" : "Properties (Click chart to view details)", left: "center", bottom: 0, textStyle: { fontSize: 11, color: "var(--text-muted)", fontWeight: "normal" } },
			tooltip: { formatter: "{b}: {c} notes" },
			series: [{
				type: "treemap",
				data: treemapData,
				roam: false,
				nodeClick: false,
				breadcrumb: { show: false },
				label: { show: true, formatter: "{b}\n({c})" }
			}]
		};

		this.chartInstanceLeft.setOption(leftOption, true);

		if (!this.selectedPropertyCategory) {
			const hasProgress = treemapData.find(d => d.name === "progress");
			this.selectedPropertyCategory = hasProgress ? "progress" : (treemapData[0]?.name || null);
		}

		this.chartInstanceLeft.on("click", (params: unknown) => {
			if (params.name) {
				this.selectedPropertyCategory = params.name;
				this.updatePropertiesDetailChart(stats);
			}
		});

		this.updatePropertiesDetailChart(stats);
	}

	private updatePropertiesDetailChart(stats: VaultStats) {
		if (!this.chartInstanceRight || !this.selectedPropertyCategory) return;
		const isVi = this.settings.language === "vi";

		const group = stats.propertiesGrouped[this.selectedPropertyCategory] || {};

		const aggregated: Record<string, number> = {};
		for (const [name, value] of Object.entries(group)) {
			let strName = String(name);
			if (this.selectedPropertyCategory === "publish" && strName.includes("T")) {
				strName = strName.split("T")[0] || strName;
			}
			aggregated[strName] = (aggregated[strName] || 0) + (value);
		}

		const detailData = Object.entries(aggregated)
			.map(([name, value]) => ({ name, value }))
			.sort((a, b) => b.value - a.value);

		const rightOption: EChartsOption = {
			backgroundColor: "transparent",
			title: { text: isVi ? `Giá trị cho '${this.selectedPropertyCategory}'` : `Values for '${this.selectedPropertyCategory}'`, left: "center", top: 10, textStyle: { fontSize: 14 } },
			tooltip: { trigger: "item" },
			xAxis: { type: "category", data: detailData.map(d => d.name), axisLabel: { interval: 0, rotate: 30 } },
			yAxis: { type: "value" },
			series: [{
				type: "bar",
				data: detailData.map(d => d.value),
				itemStyle: { color: BRAND.teal },
				label: { show: true, position: "top" }
			}]
		};

		this.chartInstanceRight.setOption(rightOption, true);

		this.chartInstanceRight.off("click");
		this.chartInstanceRight.on("click", (params: unknown) => {
			if (params.name) {
				const linktext = extractWikilinkName(String(params.name));
				const file = this.app.metadataCache.getFirstLinkpathDest(linktext, "");
				if (file) {
					this.app.workspace.getLeaf(false).openFile(file);
				}
			}
		});
	}

	private getTagsChartOption(stats: VaultStats): EChartsOption {
		const isVi = this.settings.language === "vi";

		const data = Object.entries(stats.tagsCount)
			.sort((a, b) => b[1] - a[1])
			.slice(0, 100)
			.map(([name, value]) => ({ name, value }));

		if (data.length === 0) return { title: { text: "No tags found", left: "center" } };

		return {
			title: { text: isVi ? "Top 100 thẻ" : "Top 100 Tags", left: "center", top: 10 },
			tooltip: { formatter: "{b}: {c}" },
			series: [{
				type: "treemap",
				data: data,
				roam: false,
				nodeClick: false,
				breadcrumb: { show: false },
				label: { show: true, formatter: "{b}\n({c})" },
				itemStyle: { borderColor: "#fff" }
			}]
		};
	}

	private getActivityChartOption(stats: VaultStats): EChartsOption {
		const isVi = this.settings.language === "vi";
		const timestamps = stats.activityTimestamps;

		const dailyCounts: Record<string, number> = {};
		for (const ts of timestamps) {
			const d = new Date(ts);
			const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
			dailyCounts[key] = (dailyCounts[key] || 0) + 1;
		}

		const data = Object.entries(dailyCounts).map(([date, count]) => [date, count]);
		if (data.length === 0) return { title: { text: "No activity data", left: "center" } };

		const allDates = data.map(d => d[0] as string).sort();
		const startDate = allDates[0]!;
		const endDate = allDates[allDates.length - 1]!;

		const startYear = new Date(startDate).getFullYear();
		const endYear = new Date(endDate).getFullYear();
		const maxVal = Math.max(...data.map(d => d[1] as number));

		const calendars: unknown[] = [];
		const series: unknown[] = [];

		for (let y = startYear; y <= endYear; y++) {
			const calIndex = y - startYear;
			calendars.push({
				top: 60 + calIndex * 160,
				left: 60,
				right: 40,
				cellSize: ["auto", 15],
				range: String(y),
				itemStyle: { borderWidth: 2, borderColor: "#fff", color: "#f0f7f7" },
				splitLine: { show: false },
				yearLabel: { show: true, margin: 30, fontSize: 14 },
				dayLabel: { firstDay: 1, nameMap: ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"], fontSize: 10 },
				monthLabel: { fontSize: 10 },
			});
			series.push({
				type: "heatmap",
				coordinateSystem: "calendar",
				calendarIndex: calIndex,
				data: data.filter(d => (d[0] as string).startsWith(String(y))),
			});
		}

		return {
			title: { text: isVi ? "Biểu đồ hoạt động" : "Activity Heatmap", left: "center", top: 10, textStyle: { fontSize: 14 } },
			tooltip: { formatter: (params: unknown) => `${params.value[0]}: <b>${params.value[1]}</b> note(s)` },
			visualMap: {
				min: 0,
				max: maxVal,
				calculable: true,
				orient: "horizontal",
				left: "center",
				top: calendars.length * 160 + 50,
				inRange: { color: [...HEATMAP_RAMP] },
				textStyle: { fontSize: 11 },
			},
			calendar: calendars.length === 1 ? calendars[0] : calendars,
			series: series,
		};
	}

	private getActivityByDayOfWeekOption(stats: VaultStats): EChartsOption {
		const isVi = this.settings.language === "vi";
		const timestamps = stats.activityTimestamps;
		if (timestamps.length === 0) return { title: { text: "No activity data", left: "center" } };

		const dayNames = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
		const dayCounts = [0, 0, 0, 0, 0, 0, 0];

		for (const ts of timestamps) {
			const d = new Date(ts);
			const dow = (d.getDay() + 6) % 7;
			dayCounts[dow] = (dayCounts[dow] ?? 0) + 1;
		}

		const maxCount = Math.max(...dayCounts);
		const colors = dayCounts.map(c => {
			const ratio = maxCount > 0 ? c / maxCount : 0;
			if (ratio > 0.75) return HEATMAP_RAMP[4];
			if (ratio > 0.5) return HEATMAP_RAMP[3];
			if (ratio > 0.25) return HEATMAP_RAMP[2];
			return HEATMAP_RAMP[1];
		});

		return {
			title: { text: isVi ? "Hoạt động theo thứ trong tuần" : "Activity by Day of Week", left: "center", top: 10, textStyle: { fontSize: 14 } },
			tooltip: {
				trigger: "axis",
				formatter: (params: unknown) => {
					const p = Array.isArray(params) ? params[0] : params;
					return `${p.name}: <b>${p.value}</b> ${isVi ? "hoạt động" : "activity events"}`;
				},
			},
			grid: { left: "10%", right: "10%", bottom: "15%", top: "20%" },
			xAxis: { type: "category", data: dayNames, axisLabel: { fontSize: 12 } },
			yAxis: { type: "value", name: "Events", nameTextStyle: { fontSize: 11 } },
			series: [{
				type: "bar",
				data: dayCounts.map((val, idx) => ({
					value: val,
					itemStyle: { color: colors[idx] || HEATMAP_RAMP[1], borderRadius: [4, 4, 0, 0] },
				})),
				barWidth: "50%",
				label: { show: true, position: "top", fontSize: 11 },
			}],
		};
	}

	private getMoodChartOption(stats: VaultStats): EChartsOption {
		const isVi = this.settings.language === "vi";

		const numericData: [string, number][] = Object.entries(stats.moodByDate);
		const feelingByDate = stats.feelingByDate;
		const feelingDates = Object.keys(feelingByDate).sort();

		const hasNumeric = numericData.length > 0;
		const hasFeelings = feelingDates.length > 0;

		const monthNames = isVi ? ["Thg 1", "Thg 2", "Thg 3", "Thg 4", "Thg 5", "Thg 6", "Thg 7", "Thg 8", "Thg 9", "Thg 10", "Thg 11", "Thg 12"] : ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
		const formatDate = (dateStr: string) => {
			const d = new Date(dateStr);
			const month = monthNames[d.getMonth()] || "";
			return `${month} ${d.getDate()}`;
		};

		if (!hasNumeric && !hasFeelings) {
			return {
				title: { text: isVi ? "Theo dõi tâm trạng & cảm xúc" : "Mood & Feeling Tracking", subtext: isVi ? "Không tìm thấy dữ liệu tâm trạng/cảm xúc.\nThêm 'mood: excited' hoặc 'feeling: happy' vào ghi chú để bắt đầu." : "No mood/feeling data found.\nAdd 'mood: excited' or 'feeling: happy' to your notes.", left: "center", top: "center" }
			};
		}

		if (hasFeelings) {
			const allFeelings = Object.keys(stats.feelingCounts).sort();
			const feelingColors = [...FEELING_PALETTE];

			const series: unknown[] = allFeelings.map((feeling, idx) => {
				const data: unknown[] = [];
				for (const date of feelingDates) {
					const fArr = feelingByDate[date] || [];
					if (fArr.includes(feeling)) {
						data.push({ value: [date, idx], symbolSize: 16 });
					}
				}
				return {
					name: feeling.charAt(0).toUpperCase() + feeling.slice(1),
					type: "scatter",
					data: data,
					itemStyle: { color: feelingColors[idx % feelingColors.length] },
					symbolSize: 14,
					emphasis: { scale: 1.5 },
				};
			});

			return {
				title: { text: isVi ? "Dòng thời gian cảm xúc" : "Feeling Timeline", left: "center", top: 10, textStyle: { fontSize: 14 } },
				tooltip: {
					trigger: "item",
					formatter: (params: unknown) => {
						const date = formatDate(params.value[0]);
						return `<b>${date}</b><br/>${params.seriesName}`;
					},
				},
				legend: { bottom: 40, type: "scroll", textStyle: { fontSize: 12 } },
				grid: { left: "12%", right: "5%", bottom: "20%", top: "15%" },
				xAxis: {
					type: "category",
					data: feelingDates,
					axisLabel: { formatter: (val: string) => formatDate(val), rotate: 0, fontSize: 11 },
					axisTick: { alignWithLabel: true },
				},
				yAxis: {
					type: "value",
					min: -0.5,
					max: allFeelings.length - 0.5,
					interval: 1,
					axisLabel: {
						formatter: (val: number) => {
							const idx = Math.round(val);
							if (idx >= 0 && idx < allFeelings.length) {
								const f = allFeelings[idx] || "";
								return f.charAt(0).toUpperCase() + f.slice(1);
							}
							return "";
						},
						fontSize: 11,
					},
					splitLine: { lineStyle: { type: "dashed", color: "#eee" } },
				},
				dataZoom: [{ type: "inside", xAxisIndex: 0 }, { type: "slider", xAxisIndex: 0, bottom: 10, height: 20 }],
				series,
			};
		}

		return {
			title: { text: "Mood Score Over Time", left: "center", top: 10, textStyle: { fontSize: 14 } },
			tooltip: {
				trigger: "axis",
				formatter: (params: unknown) => {
					const p = Array.isArray(params) ? params[0] : params;
					return `<b>${formatDate(p.name)}</b><br/>Mood: ${p.value}`;
				},
			},
			grid: { left: "10%", right: "5%", bottom: "20%", top: "15%" },
			xAxis: { type: "category", data: numericData.map(d => d[0]), axisLabel: { formatter: (val: string) => formatDate(val), fontSize: 11 } },
			yAxis: { type: "value", min: 1, max: 10, name: "Mood Score", nameTextStyle: { fontSize: 11 } },
			dataZoom: [{ type: "inside", xAxisIndex: 0 }, { type: "slider", xAxisIndex: 0, bottom: 10, height: 20 }],
			series: [{
				name: "Mood",
				type: "line",
				data: numericData.map(d => d[1]),
				itemStyle: { color: ACTIVITY_COLOR },
				areaStyle: { color: ACTIVITY_AREA },
				markLine: {
					data: [{ type: "average", name: "Avg" }],
					lineStyle: { color: ACTIVITY_AVGLINE },
				},
				smooth: true,
				symbolSize: 8,
			}]
		};
	}
}

import { ItemView, WorkspaceLeaf, setIcon, TFile, moment } from "obsidian";
import { FlowPluginSettings, FlowRole } from "../../../types";
import { VIEW_TYPE_TASK_SIDEBAR } from "../../../constants";

export interface TaskItem {
	file: TFile;
	line: number;
	text: string;
	status: string;
	folder: string;
    dueDate?: string;
    level?: number;
	id?: string;
	parentId?: string;
}

export class TaskSidebarView extends ItemView {
	private settings: FlowPluginSettings;
	private tasks: TaskItem[] = [];
	private activeFilter: "today" | "tomorrow" | "other" = "today";
    private refreshTimeout: NodeJS.Timeout | null = null;
    private quickInputEl: HTMLInputElement | null = null;

	constructor(leaf: WorkspaceLeaf, settings: FlowPluginSettings) {
		super(leaf);
		this.settings = settings;
	}

	getViewType() {
		return VIEW_TYPE_TASK_SIDEBAR;
	}

	getDisplayText() {
		return this.settings.language === "vi" ? "Tập trung hôm nay" : "Focus On Today";
	}

    getIcon() {
        return "check-square";
    }

	async onOpen() {
		const container = this.containerEl.children[1] as HTMLElement;
		container.empty();
		container.addClass("flow-sidebar-task-view");
        container.setCssProps({ "padding": "20px 16px" })
        container.setCssProps({ "display": "flex" })
        container.setCssProps({ "flex-direction": "column" })
        container.setCssProps({ "gap": "24px" })
        container.setCssProps({ "background": "var(--background-secondary)" })

        this.registerEvent(
            this.app.metadataCache.on("changed", () => {
                this.requestRefresh();
            })
        );

        this.registerEvent(
            this.app.vault.on("delete", () => {
                this.requestRefresh();
            })
        );

        await this.refresh();
	}

    public requestRefresh() {
        if (this.refreshTimeout) clearTimeout(this.refreshTimeout);
        this.refreshTimeout = setTimeout(() => {
            // Do not refresh if user is typing to avoid stealing focus
            if (this.quickInputEl && document.activeElement === this.quickInputEl) {
                return;
            }
            this.refresh();
        }, 1000);
    }

    public async refresh() {
        const container = this.containerEl.children[1] as HTMLElement;
        container.empty();

		// Cập nhật lại title của tab nếu có thể
		const titleEl = this.containerEl.querySelector(".view-header-title");
		if (titleEl) {
			titleEl.textContent = this.getDisplayText();
		}

        await this.loadTasks();
        this.renderHeader(container);
        this.renderStats(container);
        this.renderQuickInput(container);
        this.renderTimeline(container);
    }

    private async loadTasks() {
		this.tasks = [];
		const mdFiles = this.app.vault.getMarkdownFiles();

		for (const file of mdFiles) {
			const cache = this.app.metadataCache.getFileCache(file);
			if (!cache || !cache.listItems) continue;

			const taskItems = cache.listItems.filter(li => li.task !== undefined);
			if (taskItems.length === 0) continue;

			const content = await this.app.vault.cachedRead(file);
			const lines = content.split('\n');

			for (const li of taskItems) {
				const lineNum = li.position.start.line;
				const lineText = lines[lineNum] || "";
				const textMatch = lineText.match(/^([ \t]*)[-*+]\s+\[(.)\]\s+(.*)$/);
				let text = "";
				let level = 0;
				if (textMatch) {
					const indentStr = textMatch[1] || "";
					text = textMatch[3] || "";
					for (const char of indentStr) {
						if (char === '\t') level++;
						else if (char === ' ') level += 0.25;
					}
					level = Math.floor(level);
				} else {
					text = lineText;
				}

                // Parse due date from (@YYYY-MM-DD ...)
                const reminderMatch = text.match(/\(@(\d{4}-\d{2}-\d{2})\s+(\d{2}:\d{2})\)/);
                let dueDate = reminderMatch ? reminderMatch[1] : undefined;

                // Fallback to filename if in Track folder
                if (!dueDate && file.path.includes(this.settings.folderMap[FlowRole.TRACK])) {
                    const dateMatch = file.basename.match(/^\d{4}-\d{2}-\d{2}$/);
                    if (dateMatch) dueDate = dateMatch[0];
                }

				const idMatch = text.match(/%%id:([^%]+)%%/);
				const parentMatch = text.match(/%%parent:([^%]+)%%/);
				const id = idMatch ? idMatch[1] : undefined;
				const parentId = parentMatch ? parentMatch[1] : undefined;

				this.tasks.push({
					file,
					line: lineNum,
					text,
					status: li.task || " ",
					folder: file.parent?.path || "/",
                    dueDate,
                    level,
					id,
					parentId
				});
			}
		}
	}

    private renderHeader(container: HTMLElement) {
        const header = container.createDiv();
        header.setCssProps({ "text-align": "center" })
        header.setCssProps({ "margin": "10px 0" })

        const title = header.createEl("h2", { text: "Focus On Today" });
        title.setCssProps({ "font-size": "24px", "font-weight": "800", "color": "#00b4ff", "margin": "0", "letter-spacing": "-0.02em" })

        if (this.settings.language === "vi") {
            title.textContent = "Tập trung hôm nay";
        }
    }

    private renderStats(container: HTMLElement) {
        const statsRow = container.createDiv();
        statsRow.setCssProps({ "display": "flex", "gap": "10px", "justify-content": "space-between" })

        const today = moment().format("YYYY-MM-DD");
        const isUncompleted = (t: TaskItem) => t.status.toLowerCase() !== "x" && t.status !== "-";
        const todoTasks = this.tasks.filter(t => isUncompleted(t) && t.dueDate === today);
        const overdueTasks = this.tasks.filter(t => isUncompleted(t) && t.dueDate && t.dueDate < today);

        const createCard = (label: string, count: number, color: string, subLabel: string) => {
            const card = statsRow.createDiv();
            card.setCssProps({ "flex": `1`, "background": `transparent`, "padding": `4px`, "text-align": `center`, "border-bottom": `2px solid ${color}`, "display": `flex`, "flex-direction": `column`, "gap": `2px` })

            const val = card.createDiv();
