export function getSettingsLabels(settings: FlowPluginSettings): SettingsLabels {
	return settings.language === "en" ? LABELS_EN : LABELS_VI;
}

/**
 * Obsidian FLOW Plugin — Main entry point.
 *
 * Keeps lifecycle management minimal per AGENTS.md conventions.
 * All feature logic is delegated to separate modules.
 *
 * Performance: DashboardModal and ECharts are lazy-loaded via dynamic import()
 * to avoid bundling ~1MB of chart code into the startup path.
 */

import { Notice, Plugin, TFolder, TFile, setIcon } from "obsidian";
import type { EventRef } from "obsidian";
import { FlowPluginSettings } from "./types";
import { DEFAULT_SETTINGS, detectCurrentPreset } from "./constants";
import { FlowSettingTab } from "./settings";
import { installFlowSort } from "./core/folder-sorter";
import { TagTaxonomySuggest } from "./features/taxonomy/tag-suggest";
import { NotificationWorker } from "./features/reminders/worker";
import { TaskSidebarView } from "./features/dashboard/views/task-sidebar-view";
import { VIEW_TYPE_TASK_SIDEBAR } from "./constants";

export default class FlowPlugin extends Plugin {
	settings: FlowPluginSettings = DEFAULT_SETTINGS;

	private sortUninstall: (() => void) | undefined;
	private ribbonIconEl: HTMLElement | undefined;
	private tocEventRefs: EventRef[] = [];

	isUiRevealed: boolean = false;
	private uiToggleStatusBarItem: HTMLElement | undefined;

	async onload() {
		await this.loadSettings();

		// ── Ribbon icon (lazy-loads Dashboard on click) ─────
		if (this.settings.showRibbonIcon) {
			this.ribbonIconEl = this.addRibbonIcon(
				"waves",
				"FLOW Dashboard",
				async () => {
					const { DashboardModal } = await import("./features/dashboard/dashboard-modal");
					new DashboardModal(this.app, this.settings).open();
				}
			);
		}

		this.uiToggleStatusBarItem = this.addStatusBarItem();
		this.uiToggleStatusBarItem.addClass("flow-ui-toggle-status");
		this.uiToggleStatusBarItem.onClickEvent(() => {
			this.isUiRevealed = !this.isUiRevealed;
			this.applyUiState();
		});
		this.updateUiToggleStatusBar();

		// ── Commands ─────────────────────────────────────────
		this.addCommand({
			id: "flow-create-folders",
			name: "Create missing FLOW folders",
			callback: async () => {
				const { createMissingFlowFolders } = await import("./core/folder-manager");
				const created = await createMissingFlowFolders(
					this.app.vault,
					this.settings.folderMap
				);
				if (created.length === 0) {
					new Notice("FLOW: All folders already exist.");
				}
			},
		});

		this.addCommand({
			id: "flow-open-dashboard",
			name: "Open FLOW Dashboard",
			callback: async () => {
				const { DashboardModal } = await import("./features/dashboard/dashboard-modal");
				new DashboardModal(this.app, this.settings).open();
			},
		});

		this.addCommand({
			id: "flow-open-dashboard-tasks",
			name: "Open FLOW Dashboard (Tasks)",
			callback: async () => {
				const { DashboardModal } = await import("./features/dashboard/dashboard-modal");
				new DashboardModal(this.app, this.settings, "tasks").open();
			},
		});

		this.addCommand({
			id: "flow-open-dashboard-stats",
			name: "Open FLOW Dashboard (Statistics)",
			callback: async () => {
				const { DashboardModal } = await import("./features/dashboard/dashboard-modal");
				new DashboardModal(this.app, this.settings, "statistics").open();
			},
		});

		this.addCommand({
			id: "flow-open-dashboard-navigator",
			name: "Open FLOW Dashboard (Navigator)",
			callback: async () => {
				const { DashboardModal } = await import("./features/dashboard/dashboard-modal");
				new DashboardModal(this.app, this.settings, "navigator").open();
			},
		});

		this.addCommand({
			id: "flow-detect-preset",
			name: "Detect current preset from vault folders",
			callback: async () => {
				await this.autoDetectPresetIfNeeded(true);
			},
		});
		this.addCommand({
			id: "flow-open-task-sidebar",
			name: "Open FLOW Task Sidebar",
			callback: () => {
				this.activateTaskSidebar();
			},
		});

		this.addCommand({
			id: "flow-toggle-ui",
			name: "Toggle Zen Mode",
			callback: () => {
				this.isUiRevealed = !this.isUiRevealed;
				this.applyUiState();
			},
		});

		// ── Register Views ────────────────────────────────────
		this.registerView(
			VIEW_TYPE_TASK_SIDEBAR,
			(leaf) => new TaskSidebarView(leaf, this.settings)
		);
		// ── Settings tab ─────────────────────────────────────
		this.addSettingTab(new FlowSettingTab(this.app, this));

		// ── Tag Taxonomy Suggest ──────────────────────────────
		this.registerEditorSuggest(new TagTaxonomySuggest(this));

		// ── Lifecycle: after layout ready ────────────────────
		this.app.workspace.onLayoutReady(async () => {
			this.applyUiState();

			// Auto-detect vault preset on first run (deferred to avoid blocking startup)
			await this.autoDetectPresetIfNeeded();

			// Auto-create folders (lazy-loaded)
			if (this.settings.autoCreateFolders) {
				const { createMissingFlowFolders } = await import("./core/folder-manager");
				await createMissingFlowFolders(
					this.app.vault,
					this.settings.folderMap
				);
			}

			// Install custom sort
			if (this.settings.enableCustomSort) {
				this.sortUninstall = installFlowSort(
					this,
					this.settings.folderMap
				);
			}

			// Invalidate stats cache on vault changes
			void import("./features/dashboard/stats-collector").then(({ invalidateStatsCache }) => {
				this.registerEvent(this.app.vault.on("create", invalidateStatsCache));
				this.registerEvent(this.app.vault.on("delete", invalidateStatsCache));
				this.registerEvent(this.app.vault.on("rename", invalidateStatsCache));
				this.registerEvent(this.app.vault.on("modify", invalidateStatsCache));
			});

			// Start background notification worker
			const notificationWorker = new NotificationWorker(this);
			notificationWorker.start();

			// NOTE: TOC watcher (Phase 4) — not yet implemented.
			// Empty event handlers were removed to avoid startup overhead.

			// Execute Startup Action
			const action = this.settings.startupAction;
			if (action.startsWith("dashboard")) {
				const { DashboardModal } = await import("./features/dashboard/dashboard-modal");
				if (action === "dashboard") {
					new DashboardModal(this.app, this.settings).open();
				} else if (action === "dashboard-navigator") {
					new DashboardModal(this.app, this.settings, "navigator").open();
				} else if (action === "dashboard-tasks") {
					new DashboardModal(this.app, this.settings, "tasks").open();
				} else if (action === "dashboard-statistics") {
					new DashboardModal(this.app, this.settings, "statistics").open();
				}
			} else if (action === "graph") {
				// Internal obsidian command to open graph view
				(this.app as unknown).commands?.executeCommandById("graph:open");
			} else if (action === "file" && this.settings.startupFilePath) {
				const file = this.app.vault.getAbstractFileByPath(this.settings.startupFilePath);
				if (file instanceof TFile) {
					this.app.workspace.getLeaf(false).openFile(file);
				}
			}
		});
	}

	applyUiState() {
		const body = document.body;
		const level = this.settings.zenModeLevel;

		if (level === 0) {
			// Disable Zen mode entirely
			body.classList.remove("flow-zen-active", "flow-zen-level-1", "flow-zen-level-2", "flow-zen-fallback");
			if (this.uiToggleStatusBarItem) this.uiToggleStatusBarItem.hide();
			return;
		}

		if (this.uiToggleStatusBarItem) this.uiToggleStatusBarItem.show();

		const borderismClasses = [
			"Ribbon-autohide", 
			"tab-autohide", 
			"nav-header-autohide", 
			"tab-title-bar-autohide", 
			"vault-profile-autohide"
		];

		const activeTheme = (this.app as unknown).customCss?.theme || "";
		const isBorderism = activeTheme === "Borderism";

		if (this.isUiRevealed) {
			// Show UI
			body.classList.remove("flow-zen-active", "flow-zen-level-1", "flow-zen-level-2", "flow-zen-fallback");

			if (isBorderism) {
				borderismClasses.forEach(cls => body.classList.remove(cls));
			}

			// Expand sidebars
			const { workspace } = this.app;
			if (workspace.leftSplit) workspace.leftSplit.expand();
			if (workspace.rightSplit) workspace.rightSplit.expand();
		} else {
			// Hide UI (Zen mode)
			body.classList.add("flow-zen-active", `flow-zen-level-${level}`);
			body.classList.remove(`flow-zen-level-${level === 1 ? 2 : 1}`);

			if (isBorderism) {
				borderismClasses.forEach(cls => body.classList.add(cls));
			} else {
				body.classList.add("flow-zen-fallback");
			}

			// If level 2, collapse sidebars
			if (level === 2) {
				const { workspace } = this.app;
				if (workspace.leftSplit) workspace.leftSplit.collapse();
				if (workspace.rightSplit) workspace.rightSplit.collapse();
			}
		}

		this.updateUiToggleStatusBar();
	}

	updateUiToggleStatusBar() {
		if (!this.uiToggleStatusBarItem) return;

		this.uiToggleStatusBarItem.empty();

		if (this.isUiRevealed) {
			setIcon(this.uiToggleStatusBarItem, "maximize");
			this.uiToggleStatusBarItem.createSpan({ text: " UI" });
			this.uiToggleStatusBarItem.setCssProps({ "color": "var(--text-muted)" })
			this.uiToggleStatusBarItem.setCssProps({ "font-weight": "normal" })
		} else {
			setIcon(this.uiToggleStatusBarItem, "minimize");
			this.uiToggleStatusBarItem.createSpan({ text: " Zen" });
			this.uiToggleStatusBarItem.setCssProps({ "color": "var(--text-accent)" })
			this.uiToggleStatusBarItem.setCssProps({ "font-weight": "bold" })
		}
	}

	onunload() {
		this.uninstallSort();
		this.disableTOCWatcher();
	}

	// ── Settings persistence ─────────────────────────────────

	async loadSettings() {
		this.settings = Object.assign(
			{},
			DEFAULT_SETTINGS,
			(await this.loadData()) as Partial<FlowPluginSettings>
		);
	}

	async saveSettings() {
		await this.saveData(this.settings);
	}


	// ── Sort management ──────────────────────────────────────

	reinstallSort() {
		this.uninstallSort();
		if (this.settings.enableCustomSort) {
			this.sortUninstall = installFlowSort(
				this,
				this.settings.folderMap
			);
		}
	}

	uninstallSort() {
		if (this.sortUninstall) {
			this.sortUninstall();
			this.sortUninstall = undefined;

			// Request default sort to clean up
			const leaf =
				this.app.workspace.getLeavesOfType("file-explorer")?.[0];
			const view = leaf?.view as Record<string, unknown> | undefined;
			if (view && typeof view.requestSort === "function") {
				(view.requestSort as () => void)();
			}
		}
	}

	// ── TOC watcher (Phase 4 — not yet implemented) ─────────
	// Stubs kept for settings UI compatibility.
	// When Phase 4 is implemented, these should register debounced
	// vault event handlers for automatic TOC regeneration.

	enableTOCWatcher() {
		// TODO: Phase 4 — register debounced vault events for TOC regeneration
		// Empty handlers were removed to avoid startup overhead on mobile.
	}

	disableTOCWatcher() {
		for (const ref of this.tocEventRefs) {
			this.app.vault.offref(ref);
		}
		this.tocEventRefs = [];
	}

	// ── Auto-detect vault's FLOW preset ──────────────────────

	/**
	 * Scans root-level folders and detects which FLOW preset matches.
	 * On first run (no data saved), automatically applies the detected preset.
	 * @param force If true, always detect and apply (used by command)
	 */
	private async autoDetectPresetIfNeeded(force = false) {
		const savedData = await this.loadData();

		// Only auto-detect on first run (no saved settings) or when forced
		if (savedData && !force) return;

		const rootFolders = this.app.vault
			.getRoot()
			.children.filter((f): f is TFolder => f instanceof TFolder)
			.map((f) => f.name);

		const detected = detectCurrentPreset(rootFolders);

		if (detected) {
			this.settings.presetId = detected.presetId;
			this.settings.folderMap = detected.folderMap;
			this.settings.useNumberPrefix = detected.usePrefix;
			await this.saveSettings();
			new Notice(
				`FLOW: Detected "${detected.presetId}" preset from existing vault folders.`
			);
		} else if (force) {
			new Notice(
				"FLOW: Could not detect a matching preset from vault folders."
			);
		}
	}

	async activateTaskSidebar() {
		const { workspace } = this.app;

		let leaf = workspace.getLeavesOfType(VIEW_TYPE_TASK_SIDEBAR)[0];

		if (!leaf) {
			const rightLeaf = workspace.getRightLeaf(false);
			if (!rightLeaf) return;
			leaf = rightLeaf;
			await leaf.setViewState({
				type: VIEW_TYPE_TASK_SIDEBAR,
				active: true,
			});
		}

		workspace.revealLeaf(leaf);
	}
}

import { Setting, Notice } from "obsidian";
import type FlowPlugin from "../../main";
import { FLOW_PRESETS, getPresetById, applyPrefixFormat } from "../../constants";
import { FLOW_ROLE_ORDER, FLOW_ROLE_DESCRIPTIONS } from "../../types";
import { renameFlowFolders, syncObsidianConfigs } from "../../core/folder-manager";
import type { FlowSettingTab } from "../../settings";
import { getSettingsLabels } from "../../i18n/settings-labels";

export class FoldersTab {
	constructor(private plugin: FlowPlugin, private settingTab: FlowSettingTab) {}

	display(containerEl: HTMLElement): void {
		const L = getSettingsLabels(this.plugin.settings);
		const section = containerEl.createDiv("flow-section");

		// Preset selector
		new Setting(section)
			.setName(L.folderPreset)
			.setDesc(L.folderPresetDesc)
			.addDropdown((dropdown) => {
				for (const preset of FLOW_PRESETS) {
					dropdown.addOption(preset.id, preset.label);
				}
				dropdown.addOption("custom", "Custom (tùy chỉnh)");

				dropdown.setValue(this.plugin.settings.presetId);
				dropdown.onChange(async (value) => {
					const oldMap = { ...this.plugin.settings.folderMap };
					this.plugin.settings.presetId = value;

					if (value !== "custom") {
						const preset = getPresetById(value);
						if (preset) {
							this.plugin.settings.folderMap = applyPrefixFormat(
								preset.folders,
								this.plugin.settings.useNumberPrefix
							);
							this.plugin.settings.roleDescriptions = { ...preset.descriptions };
						}
					}

					await this.plugin.saveSettings();

					const newMap = this.plugin.settings.folderMap;
					const renamedPairs = await renameFlowFolders(this.plugin.app.vault, oldMap, newMap);
					await syncObsidianConfigs(this.plugin.app.vault, oldMap, newMap);

					this.plugin.reinstallSort();
					this.settingTab.display();
				});
			});

		// Number prefix toggle
		new Setting(section)
			.setName(L.numberPrefix)
			.setDesc(L.numberPrefixDesc)
			.addToggle((toggle) => {
				toggle.setValue(this.plugin.settings.useNumberPrefix);
				toggle.onChange(async (value) => {
					this.plugin.settings.useNumberPrefix = value;

					const oldMap = { ...this.plugin.settings.folderMap };
					const newMap = applyPrefixFormat(oldMap, value);

					this.plugin.settings.folderMap = newMap;
					await this.plugin.saveSettings();

					new Notice(L.renamingNotice, 7000);

					const renamedPairs2 = await renameFlowFolders(this.plugin.app.vault, oldMap, newMap);
					await syncObsidianConfigs(this.plugin.app.vault, oldMap, newMap);
					this.plugin.reinstallSort();
					this.settingTab.display();
				});
			});

		// Auto-create folders on startup
		new Setting(section)
			.setName(L.autoCreate)
			.setDesc(L.autoCreateDesc)
			.addToggle((toggle) => {
				toggle.setValue(this.plugin.settings.autoCreateFolders);
				toggle.onChange(async (value) => {
					this.plugin.settings.autoCreateFolders = value;
					await this.plugin.saveSettings();
					if (value) {
						const { createMissingFlowFolders } = await import("../../core/folder-manager");
						const created = await createMissingFlowFolders(
							this.plugin.app.vault,
							this.plugin.settings.folderMap
						);
						if (created.length === 0) {
							new Notice("FLOW: All folders already exist.");
						}
					}
				});
			});

		// Custom sort toggle
		new Setting(section)
			.setName(L.customSort)
			.setDesc(L.customSortDesc)
			.addToggle((toggle) => {
				toggle.setValue(this.plugin.settings.enableCustomSort);
				toggle.onChange(async (value) => {
					this.plugin.settings.enableCustomSort = value;
					await this.plugin.saveSettings();
					if (value) {
						this.plugin.reinstallSort();
						new Notice("FLOW: Custom sort enabled.");
					} else {
						this.plugin.uninstallSort();
						new Notice("FLOW: Custom sort disabled.");
					}
				});
			});

		// Folder name editors
		const isCustom = this.plugin.settings.presetId === "custom";

		const namesSection = containerEl.createDiv("flow-section");
		namesSection.createEl("h3", { text: L.folderNames });
		if (!isCustom) {
			namesSection.createEl("p", {
				text: L.switchToCustom,
				cls: "setting-item-description",
			});
		}

		for (const role of FLOW_ROLE_ORDER) {
			const roleLabel = role.charAt(0).toUpperCase() + role.slice(1);
			const roleIndex = FLOW_ROLE_ORDER.indexOf(role) + 1;

			const setting = new Setting(namesSection)
				.setName(`${roleIndex}. ${roleLabel}`)
				.setDesc(isCustom ? "Tùy chỉnh tên thư mục (trái) và mô tả hiển thị trên Dashboard (phải/dưới)" : this.plugin.settings.roleDescriptions[role]);

			setting.addText((text) => {
				text
					.setPlaceholder("Tên thư mục")
					.setValue(this.plugin.settings.folderMap[role])
					.setDisabled(!isCustom)
					.onChange(async (value) => {
						if (isCustom && value.trim()) {
							const oldMap = { ...this.plugin.settings.folderMap };
							this.plugin.settings.folderMap[role] = value.trim();
							await this.plugin.saveSettings();
							await renameFlowFolders(this.plugin.app.vault, oldMap, this.plugin.settings.folderMap);
							await syncObsidianConfigs(this.plugin.app.vault, oldMap, this.plugin.settings.folderMap);
							this.plugin.reinstallSort();
						}
					});
				text.inputEl.setCssProps({ "width": isCustom ? "160px" : "180px" })
			});

			if (isCustom) {
				setting.addTextArea((text) => {
					text
						.setPlaceholder("Mô tả ý nghĩa...")
						.setValue(this.plugin.settings.roleDescriptions[role])
						.onChange(async (value) => {
							this.plugin.settings.roleDescriptions[role] = value.trim();
							await this.plugin.saveSettings();
						});
					text.inputEl.setCssProps({ "width": "240px" })
					text.inputEl.setCssProps({ "height": "2.2em" }) // compact height
					text.inputEl.setCssProps({ "min-height": "2.2em" })
					text.inputEl.setCssProps({ "resize": "vertical" })
				});

				// Stack inputs horizontally with gap, or let them wrap naturally
				setting.controlEl.setCssProps({ "display": "flex" })
				setting.controlEl.setCssProps({ "flex-wrap": "wrap" })
				setting.controlEl.setCssProps({ "justify-content": "flex-end" })
				setting.controlEl.setCssProps({ "gap": "8px" })
			}
		}
	}
}

import { Setting, Notice, AbstractInputSuggest, App, TFile } from "obsidian";
import type FlowPlugin from "../../main";
import { FLOW_ROLE_ORDER, FlowRole, FLOW_ROLE_DESCRIPTIONS } from "../../types";
import { generateTOCFiles, getExistingFlowRoles } from "../../features/toc/toc-generator";
import type { FlowSettingTab } from "../../settings";
import { getSettingsLabels } from "../../i18n/settings-labels";

class FileSuggest extends AbstractInputSuggest<TFile> {
	textInputEl: HTMLInputElement;

	constructor(app: App, textInputEl: HTMLInputElement) {
		super(app, textInputEl);
		this.textInputEl = textInputEl;
	}

	getSuggestions(inputStr: string): TFile[] {
		const files = this.app.vault.getMarkdownFiles();
		if (inputStr === "") {
			return files.slice(0, 10);
		}
		const lowerCaseInputStr = inputStr.toLowerCase();
		return files
			.filter((file) => file.path.toLowerCase().includes(lowerCaseInputStr))
			.slice(0, 10);
	}

	renderSuggestion(file: TFile, el: HTMLElement): void {
		el.setText(file.path);
	}

	selectSuggestion(file: TFile): void {
		this.textInputEl.value = file.path;
		this.textInputEl.trigger("input");
		this.close();
	}
}

export class GeneralTab {
	constructor(private plugin: FlowPlugin, private settingTab: FlowSettingTab) {}

	display(containerEl: HTMLElement): void {
		const L = getSettingsLabels(this.plugin.settings);
		const section = containerEl.createDiv("flow-section");

		new Setting(section)
			.setName(L.showRibbonIcon)
			.setDesc(L.showRibbonIconDesc)
			.addToggle((toggle) => {
				toggle.setValue(this.plugin.settings.showRibbonIcon);
				toggle.onChange(async (value) => {
					this.plugin.settings.showRibbonIcon = value;
					await this.plugin.saveSettings();
					new Notice(
						`FLOW: Ribbon icon ${value ? "enabled" : "disabled"}. ${L.ribbonReload}`
					);
				});
			});

		new Setting(section)
			.setName(L.dashboardRefresh)
			.setDesc(L.dashboardRefreshDesc)
			.addDropdown((dropdown) => {
				dropdown.addOption("0", L.disabled);
				dropdown.addOption("5", `5 ${L.minutes}`);
				dropdown.addOption("15", `15 ${L.minutes}`);
				dropdown.addOption("30", `30 ${L.minutes}`);
				dropdown.addOption("60", L.hour1);
				dropdown.addOption("120", L.hours2);
				dropdown.setValue(String(this.plugin.settings.dashboardRefreshIntervalMin));
				dropdown.onChange(async (value) => {
					this.plugin.settings.dashboardRefreshIntervalMin = Number(value);
					await this.plugin.saveSettings();
					new Notice(`FLOW: Dashboard refresh → ${value === "0" ? L.disabled : value + " " + L.minutes}.`);
				});
			});

		new Setting(section)
			.setName(L.pluginLanguage)
			.setDesc(L.pluginLanguageDesc)
			.addDropdown((dropdown) => {
				dropdown.addOption("vi", "🇻🇳 Tiếng Việt");
				dropdown.addOption("en", "🇺🇸 English");
				dropdown.setValue(this.plugin.settings.language || "vi");
				dropdown.onChange(async (value) => {
					this.plugin.settings.language = value as "vi" | "en";
					await this.plugin.saveSettings();
					new Notice(`FLOW: Language → ${value === "vi" ? "Tiếng Việt" : "English"}.`);
					// Re-render settings to apply language change immediately
					this.settingTab.display();

					// Trigger sidebar view refresh
					const { workspace } = this.plugin.app;
					const leaves = workspace.getLeavesOfType("flow-task-sidebar-view");
					leaves.forEach(leaf => {
						if (leaf.view && typeof (leaf.view as unknown).refresh === "function") {
							(leaf.view as unknown).refresh();
						}
					});
				});
			});

		const isVi = this.plugin.settings.language === "vi";

		new Setting(section)
			.setName(isVi ? "Màn hình chào mừng (Startup)" : "Welcome Screen (Startup)")
			.setDesc(isVi ? "Hành động được kích hoạt tự động khi bạn mở ứng dụng." : "Action to perform automatically when opening the app.")
			.addDropdown((dropdown) => {
				dropdown.addOption("none", isVi ? "Không làm gì" : "None");
				dropdown.addOption("dashboard", isVi ? "Dashboard: Tổng quan" : "Dashboard: Overview");
				dropdown.addOption("dashboard-navigator", isVi ? "Dashboard: Bảng nội dung" : "Dashboard: Navigator");
				dropdown.addOption("dashboard-tasks", isVi ? "Dashboard: Nhiệm vụ" : "Dashboard: Tasks");
				dropdown.addOption("dashboard-statistics", isVi ? "Dashboard: Thống kê" : "Dashboard: Statistics");
				dropdown.addOption("graph", isVi ? "Mở Graph View" : "Open Graph View");
				dropdown.addOption("file", isVi ? "Mở 1 File cố định" : "Open Specific File");
				dropdown.setValue(this.plugin.settings.startupAction || "none");
				dropdown.onChange(async (value) => {
					this.plugin.settings.startupAction = value as unknown;
					await this.plugin.saveSettings();
					this.settingTab.display();
				});
			});

		if (this.plugin.settings.startupAction === "file") {
			new Setting(section)
				.setName(isVi ? "Đường dẫn File cố định" : "Specific File Path")
				.setDesc(isVi ? "Đường dẫn tới file (ví dụ: 1. Capture/Inbox.md). Gõ để tìm kiếm file." : "Path to the markdown file (e.g. 1. Capture/Inbox.md). Type to search.")
				.addText((text) => {
					text.setPlaceholder("Folder/File.md");
					text.setValue(this.plugin.settings.startupFilePath || "");
					new FileSuggest(this.plugin.app, text.inputEl);
					text.onChange(async (value) => {
						this.plugin.settings.startupFilePath = value;
						await this.plugin.saveSettings();
					});
				});
		}

		new Setting(section)
			.setName("Cấp độ Zen Mode (Mặc định)")
			.setDesc("0: Tắt. 1: Ẩn Ribbon, Title bar, Tabs, Vault profile. 2: Ẩn thêm cả hai Sidebars.")
			.addDropdown((dropdown) => {
				dropdown
					.addOption("0", "Tắt (Off)")
					.addOption("1", "Level 1 (Focus)")
					.addOption("2", "Level 2 (Clean)")
					.setValue(this.plugin.settings.zenModeLevel.toString())
					.onChange(async (value) => {
						this.plugin.settings.zenModeLevel = parseInt(value) as 0 | 1 | 2;
						await this.plugin.saveSettings();
						// always re-apply to trigger cleanup or setup
						this.plugin.applyUiState();
					});
			});

		// TOC section
		const tocSection = containerEl.createDiv("flow-section");
		tocSection.createEl("h3", { text: L.tocSection });

		new Setting(tocSection)
			.setName(L.autoToc)
			.setDesc(L.autoTocDesc)
			.addToggle((toggle) => {
				toggle.setValue(this.plugin.settings.autoTOC);
				toggle.onChange(async (value) => {
					this.plugin.settings.autoTOC = value;
					await this.plugin.saveSettings();
					if (value) {
						this.plugin.enableTOCWatcher();
						new Notice("FLOW: Auto-TOC watcher enabled.");
					} else {
						this.plugin.disableTOCWatcher();
						new Notice("FLOW: Auto-TOC watcher disabled.");
					}
				});
			});

		new Setting(tocSection)
			.setName(L.includeDataview)
			.setDesc(L.includeDataviewDesc)
			.addToggle((toggle) => {
				toggle.setValue(this.plugin.settings.tocDataViewQueries);
				toggle.onChange(async (value) => {
					this.plugin.settings.tocDataViewQueries = value;
					await this.plugin.saveSettings();
					new Notice(`FLOW: DataView queries in TOC ${value ? "enabled" : "disabled"}.`);
				});
			});

		// ── Folder checkboxes (only when auto-TOC is enabled) ──
		if (this.plugin.settings.autoTOC) {
			const checkboxSection = containerEl.createDiv("flow-section");
			checkboxSection.createEl("h3", { text: L.generateTocFor });
			checkboxSection.createEl("p", {
				text: L.generateTocForDesc,
				cls: "setting-item-description",
			});

			const existingRoles = getExistingFlowRoles(
				this.plugin.app.vault,
				this.plugin.settings.folderMap
			);

			for (const role of FLOW_ROLE_ORDER) {
				const folderName = this.plugin.settings.folderMap[role];
				const exists = existingRoles.includes(role);

				new Setting(checkboxSection)
					.setName(`${folderName}`)
					.setDesc(exists ? (this.plugin.settings.roleDescriptions[role] || FLOW_ROLE_DESCRIPTIONS[role]) : "⚠ Folder does not exist")
					.addToggle((toggle) => {
						toggle.setValue(this.settingTab.tocSelectedRoles.has(role) && exists);
						toggle.setDisabled(!exists);
						toggle.onChange((value) => {
							if (value) {
								this.settingTab.tocSelectedRoles.add(role);
							} else {
								this.settingTab.tocSelectedRoles.delete(role);
							}
						});
					});
			}

			// Generate button
			new Setting(checkboxSection)
				.setName("")
				.setDesc("")
				.addButton((button) => {
					button
						.setButtonText(L.generateTocBtn)
						.setCta()
						.onClick(async () => {
							const selectedRoles = FLOW_ROLE_ORDER.filter((r) =>
								this.settingTab.tocSelectedRoles.has(r) && existingRoles.includes(r)
							);

							if (selectedRoles.length === 0) {
								new Notice("FLOW: No folders selected for TOC generation.");
								return;
							}

							const count = await generateTOCFiles(
								this.plugin.app.vault,
								this.plugin.settings.folderMap,
								selectedRoles,
								this.plugin.settings.tocDataViewQueries
							);

							new Notice(
								`FLOW: Generated ${count} TOC file(s) in: ${selectedRoles.map((r) => this.plugin.settings.folderMap[r]).join(", ")}`
							);
						});
				});
		}

		// ── Settings Data Management ──────────
		const dataSection = containerEl.createDiv("flow-section");
		dataSection.createEl("h3", { text: isVi ? "Quản lý Dữ liệu" : "Data Management" });
		dataSection.createEl("p", {
			text: isVi ? "Nhập hoặc xuất cấu hình FLOW của bạn thành file JSON." : "Import or export your FLOW settings as a JSON file.",
			cls: "setting-item-description",
		});

		new Setting(dataSection)
			.setName(isVi ? "Xuất cấu hình" : "Export Settings")
			.setDesc(isVi ? "Lưu cấu hình hiện tại thành file JSON để sao lưu." : "Save your current configuration to a file.")
			.addButton((button) => {
				button.setButtonText(isVi ? "Xuất" : "Export").onClick(() => {
					const data = JSON.stringify(this.plugin.settings, null, 2);
					const blob = new Blob([data], { type: "application/json" });
					const url = URL.createObjectURL(blob);
					const a = document.createElement("a");
					a.href = url;
					a.download = "obsidian-flow-settings.json";
					a.click();
					URL.revokeObjectURL(url);
					new Notice(isVi ? "FLOW: Đã xuất cấu hình thành công." : "FLOW: Settings exported successfully.");
				});
			});

		new Setting(dataSection)
			.setName(isVi ? "Nhập cấu hình" : "Import Settings")
			.setDesc(isVi ? "Tải cấu hình từ file JSON (chú ý: ghi đè cấu hình hiện tại)." : "Load your configuration from a JSON file (overwrites current settings).")
			.addButton((button) => {
				button.setButtonText(isVi ? "Nhập" : "Import").onClick(() => {
					const input = document.createElement("input");
					input.type = "file";
					input.accept = ".json";
					input.onchange = async (e) => {
						const file = (e.target as HTMLInputElement).files?.[0];
						if (file) {
							const reader = new FileReader();
							reader.onload = async (e) => {
								try {
									const data = JSON.parse(e.target?.result as string);
									this.plugin.settings = Object.assign({}, this.plugin.settings, data);
									await this.plugin.saveSettings();
									this.settingTab.display();
									new Notice(isVi ? "FLOW: Đã nhập cấu hình thành công." : "FLOW: Settings imported successfully.");
								} catch (err) {
									new Notice(isVi ? "FLOW: File JSON không hợp lệ." : "FLOW: Invalid JSON file.");
								}
							};
							reader.readAsText(file);
						}
					};
					input.click();
				});
			});

		// ── FLOW Vault Template Section ──
		const templateSection = containerEl.createDiv("flow-section");
		templateSection.createEl("h3", { text: L.vaultTemplate });
		templateSection.createEl("p", {
			text: L.vaultTemplateDesc,
			cls: "setting-item-description",
		});

		new Setting(templateSection)
			.setName("Learn Anything")
			.setDesc("https://learn-anything.vn/download-obsidian-flow")
			.addButton((button) => {
				button
					.setButtonText(L.downloadBtn)
					.setCta()
					.onClick(() => {
						window.open("https://learn-anything.vn/download-obsidian-flow", "_blank");
					});
			});

		// ── Credits & Support ──
		const creditSection = containerEl.createDiv("flow-credits-section");

		creditSection.createEl("h4", { text: "Credits & Support", cls: "flow-credits-title" });

		// Add Logo Link
		const logoLink = creditSection.createEl("a");
		logoLink.href = "http://learn-anything.vn";
		logoLink.target = "_blank";
		logoLink.addClass("flow-credits-logo-link");

		const logo = logoLink.createEl("img");
		logo.addClass("flow-credits-logo");
		logo.src = "https://learn-anything.vn/img/logo-learn-anything-new-rec_trans.png";
		logo.onerror = () => {
			try {
				const adapter = this.plugin.app.vault.adapter as unknown as Record<string, unknown>;
				if (typeof adapter.getResourcePath === "function") {
					const basePath = typeof adapter.getBasePath === "function" ? (adapter.getBasePath as () => string)() : "";
					logo.src = `app://local/${basePath}/${this.plugin.app.vault.configDir}/plugins/obsidian-flow/learn-anything-logo-rec-trans.png`;
				}
			} catch { /* ignore */ }
		};

		// i18n strings for credits
		const isViCred = this.plugin.settings.language !== "en";
		const authorPrefix = isViCred ? "Tác giả: " : "Author: ";
		const flowLabel = isViCred ? "Phương pháp FLOW PKM" : "FLOW PKM Methodology";
		const courseLabel = isViCred ? "Khoá học Obsidian FLOW" : "Obsidian FLOW Course";

		const createCreditLink = (parent: HTMLElement, text: string, href: string) => {
			const link = parent.createEl("a", { text, href });
			link.target = "_blank";
			link.addClass("flow-credits-link");
			return link;
		};

		const authorLine = creditSection.createEl("div");
		authorLine.addClass("flow-credits-text-line", "flow-credits-text-line-top");
		authorLine.appendChild(document.createTextNode(`${authorPrefix}Thịnh Vũ | `));
		createCreditLink(authorLine, "Website", "http://learn-anything.vn");

		const resourcesLine = creditSection.createEl("div");
		resourcesLine.addClass("flow-credits-text-line", "flow-credits-text-line-bottom");
		createCreditLink(resourcesLine, flowLabel, "https://learn-anything.vn/download-obsidian-flow");
		resourcesLine.appendChild(document.createTextNode(" | "));
		createCreditLink(resourcesLine, courseLabel, "https://learn-anything.vn/khoa-hoc/lp-khoa-hoc-obsidian-flow");
	}
}

import { Setting, Notice } from "obsidian";
import type FlowPlugin from "../../main";
import type { RemindersSettings } from "../../types";
import { getSettingsLabels } from "../../i18n/settings-labels";
import { REMINDER_MESSAGES } from "../../features/reminders/constants";

export class RemindersTab {
	constructor(private plugin: FlowPlugin) {}

	display(containerEl: HTMLElement): void {
		const L = getSettingsLabels(this.plugin.settings);
		const section = containerEl.createDiv("flow-section");

		new Setting(section)
			.setName(L.checkInterval)
			.setDesc(L.checkIntervalDesc)
			.addText((text) => {
				text
					.setPlaceholder("3600")
					.setValue(String(this.plugin.settings.reminderCheckIntervalSec))
					.onChange(async (value) => {
						const num = parseInt(value, 10);
						if (!isNaN(num) && num >= 60) {
							this.plugin.settings.reminderCheckIntervalSec = num;
							await this.plugin.saveSettings();
							new Notice(`FLOW: Reminder interval → ${num}s. Reload to apply.`);
						}
					});
			});

		const typesSection = containerEl.createDiv("flow-section");
		typesSection.createEl("h3", { text: L.reminderTypes });

		const reminderTypes: {
			key: keyof RemindersSettings;
			nameKey: keyof typeof L;
			descKey: keyof typeof L;
		}[] = [
			{ key: "consolidateCapture", nameKey: "consolidateCapture", descKey: "consolidateCaptureDesc" },
			{ key: "dailyNote", nameKey: "dailyNote", descKey: "dailyNoteDesc" },
			{ key: "weeklyReview", nameKey: "weeklyReview", descKey: "weeklyReviewDesc" },
			{ key: "publishContent", nameKey: "publishContent", descKey: "publishContentDesc" },
			{ key: "forgeCleanup", nameKey: "forgeCleanup", descKey: "forgeCleanupDesc" },
		];

		const isVi = this.plugin.settings.language !== "en";
		const daysLabels = isVi ? ["CN", "T2", "T3", "T4", "T5", "T6", "T7"] : ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

		for (const rt of reminderTypes) {
			const reminderKey = rt.key;
			const rtName = L[rt.nameKey];
			const rtDesc = L[rt.descKey];
			const config = this.plugin.settings.reminders[reminderKey];

			const group = typesSection.createDiv();
			group.addClass("flow-reminder-group");

			new Setting(group)
				.setName(rtName)
				.setDesc(rtDesc)
				.addToggle((toggle) => {
					toggle.setValue(config.enabled);
					toggle.onChange(async (value) => {
						config.enabled = value;
						await this.plugin.saveSettings();
						new Notice(`FLOW: "${rtName}" ${value ? "enabled" : "disabled"}.`);
					});
				})
				.addButton((button) => {
					button
						.setButtonText("🔔 Test")
						.setTooltip("Preview this reminder — fires in 3s")
						.onClick(() => {
							new Notice("⏳ Test notification will fire in 3 seconds...");
							const msg = REMINDER_MESSAGES[reminderKey];
							setTimeout(() => {
								// Always show an internal notice to ensure visibility
								new Notice(`🔔 FLOW: ${msg}`, 10000);
								if ("Notification" in window && Notification.permission === "granted") {
									new Notification(`FLOW: ${rtName}`, { body: msg, icon: "🔔" });
								} else if ("Notification" in window && Notification.permission !== "denied") {
									void Notification.requestPermission().then(perm => {
										if (perm === "granted") {
											new Notification(`FLOW: ${rtName}`, { body: msg, icon: "🔔" });
										}
									});
								}
							}, 3000);
						});
				});

			// Days of week setting
			const daysSetting = new Setting(group)
				.setName(isVi ? "Ngày hoạt động" : "Active Days")
				.setDesc(isVi ? "Chọn các ngày trong tuần sẽ nhận được thông báo này." : "Select which days of the week this reminder is active.");

			const daysControl = daysSetting.controlEl;
			daysControl.addClass("flow-reminder-days-container");

			daysLabels.forEach((lbl, index) => {
				const chip = daysControl.createEl("label");
				// Reusing the feeling chip style for a quick nice look, or create a specific one
				chip.addClass("flow-reminder-day-chip");
				const isActive = config.activeDays?.includes(index) ?? true;
				if (isActive) chip.addClass("is-active");

				const cb = chip.createEl("input", { type: "checkbox" });
				cb.checked = isActive;
				cb.setCssProps({ "display": "none" })

				chip.createSpan({ text: lbl });

				cb.onchange = async () => {
					let days = config.activeDays ?? [0, 1, 2, 3, 4, 5, 6];
					if (cb.checked) {
						if (!days.includes(index)) days.push(index);
					} else {
						days = days.filter(d => d !== index);
					}
					days.sort();
					config.activeDays = days;
					await this.plugin.saveSettings();

					if (cb.checked) chip.addClass("is-active");
					else chip.removeClass("is-active");
				};
			});

			// Time window setting
			new Setting(group)
				.setName(isVi ? "Khung giờ" : "Time Window")
				.setDesc(isVi ? "Chỉ hiển thị nhắc nhở trong khoảng thời gian này." : "Only trigger reminders within this time window.")
				.addText(text => {
					text.inputEl.type = "time";
					text.setValue(config.activeStartTime ?? "08:00");
					text.onChange(async val => {
						config.activeStartTime = val;
						await this.plugin.saveSettings();
					});
				})
				.addText(text => {
					text.inputEl.type = "time";
					text.setValue(config.activeEndTime ?? "22:00");
					text.onChange(async val => {
						config.activeEndTime = val;
						await this.plugin.saveSettings();
					});
				});
		}
	}
}

import { App, Setting, Notice, setIcon, TFile, TFolder } from "obsidian";
import type FlowPlugin from "../../main";
import { FlowRole, TagNode } from "../../types";
import { findExistingFlowFolder, findFlowFolderByRole } from "../../core/folder-manager";
import { detectBlueprintMissions } from "../../core/blueprint-detect";
import type { FlowSettingTab } from "../../settings";
import { getSettingsLabels } from "../../i18n/settings-labels";

export class TaxonomyTab {
	constructor(private plugin: FlowPlugin, private settingTab: FlowSettingTab) {}

	display(containerEl: HTMLElement): void {
		const L = getSettingsLabels(this.plugin.settings);

		// ── Section 1: Progress Lifecycle ────────────────────
		const lifecycleSection = containerEl.createDiv("flow-section");
		lifecycleSection.createEl("h3", { text: L.progressLifecycle });
		lifecycleSection.createEl("p", {
			text: L.progressLifecycleDesc,
			cls: "setting-item-description",
		});

		const stages = this.plugin.settings.progressLifecycle?.stages || ["raw", "medium", "done", "archived"];

		const renderLifecycleList = () => {
			const listEl = lifecycleSection.querySelector(".flow-lifecycle-list");
			if (listEl) listEl.remove();

			const list = lifecycleSection.createDiv("flow-lifecycle-list");
			list.addClass("flow-taxonomy-lifecycle-list");

			stages.forEach((stage, idx) => {
				const chip = list.createDiv();
				chip.addClass("flow-taxonomy-lifecycle-chip");

				const input = chip.createEl("input", { type: "text" });
				input.value = stage;
				input.addClass("flow-taxonomy-lifecycle-input");

				input.onchange = async () => {
					const oldVal = stages[idx] || "";
					const newVal = input.value.trim().toLowerCase();
					if (newVal && newVal !== oldVal) {
						stages[idx] = newVal;
